﻿'use strict';

// ══════════════════════════════════════════════════════
//  KATHA / PODCAST DATA
// ══════════════════════════════════════════════════════
function initCalendar(){
  let calYear = 2026;
  let calMonth = new Date().getMonth(); // current month

  // Build month picker
  const grid = document.getElementById('cal-month-grid');
  if(!grid) return;
  const now = new Date();
  const ENG_MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  CAL_MONTHS_HI.forEach((m, i) => {
    const btn = document.createElement('button');
    btn.className = 'cal-month-btn' + (i === now.getMonth() && calYear === now.getFullYear() ? ' current-month' : '');
    btn.innerHTML = `<span class="cal-month-hi">${m}</span><span class="cal-month-eng">${ENG_MONTHS[i]}</span>`;
    btn.addEventListener('click', () => openCalMonth(i));
    grid.appendChild(btn);
  });

  // Nav buttons
  document.getElementById('cal-prev')?.addEventListener('click', () => {
    calMonth = (calMonth - 1 + 12) % 12;
    if(calMonth === 11) calYear--;
    renderCalGrid(calYear, calMonth);
  });
  document.getElementById('cal-next')?.addEventListener('click', () => {
    calMonth = (calMonth + 1) % 12;
    if(calMonth === 0) calYear++;
    renderCalGrid(calYear, calMonth);
  });
  document.getElementById('cal-back-months')?.addEventListener('click', () => {
    document.getElementById('cal-month-picker').classList.remove('hidden');
    document.getElementById('cal-grid-view').classList.add('hidden');
  });

  function openCalMonth(m) {
    calMonth = m;
    document.getElementById('cal-month-picker').classList.add('hidden');
    document.getElementById('cal-grid-view').classList.remove('hidden');
    renderCalGrid(calYear, calMonth);
  }

  function renderCalGrid(year, month) {
    const grid = document.getElementById('cal-grid');
    const titleEl = document.getElementById('cal-month-title');
    if(!grid) return;

    titleEl.textContent = `${CAL_MONTHS_EN[month]} (${year})`;
    grid.innerHTML = '';

    const firstDay = new Date(year, month, 1).getDay();
    const daysInMonth = new Date(year, month + 1, 0).getDate();
    const today = new Date();
    let tithiOffset = ((month * 29) + 7) % 30; // approximate offset per month

    // Empty cells before 1st
    for(let i = 0; i < firstDay; i++){
      const empty = document.createElement('div');
      empty.className = 'cal-cell empty';
      grid.appendChild(empty);
    }

    for(let d = 1; d <= daysInMonth; d++){
      const cell = document.createElement('div');
      const dayOfWeek = new Date(year, month, d).getDay();
      const festKey = `${month}-${d}`;
      const festival = CAL_FESTIVALS[festKey];
      const tithi = TITHIS[(tithiOffset + d - 1) % 30];
      const isToday = (d === today.getDate() && month === today.getMonth() && year === today.getFullYear());

      cell.className = 'cal-cell' +
        (isToday ? ' today' : '') +
        (festival ? ' festival' : '') +
        (dayOfWeek === 0 ? ' sunday' : '');

      cell.innerHTML = `
        <span class="cal-date-num">${d}</span>
        <span class="cal-tithi">${festival ? festival.replace(/[🌞🇮🇳🔱🎨🏹🐒💛🌕🌊🌕🐍🎀🦚🐘🦁🏺🪔🎄📖]/u,'') : tithi}</span>
        ${festival ? '<div class="cal-festival-dot"></div>' : ''}`;

      cell.addEventListener('click', () => {
        document.querySelectorAll('.cal-cell.selected').forEach(c => c.classList.remove('selected'));
        cell.classList.add('selected');
        showEvent(d, dayOfWeek, festival || tithi);
      });

      grid.appendChild(cell);
    }

    // Hide event card on re-render
    document.getElementById('cal-event-card')?.classList.add('hidden');
  }

  function showEvent(d, dow, event) {
    const days = ['रविवार','सोमवार','मंगलवार','बुधवार','गुरुवार','शुक्रवार','शनिवार'];
    const daysEn = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
    const card = document.getElementById('cal-event-card');
    document.getElementById('cal-event-day').innerHTML =
      `<strong>${String(d).padStart(2,'0')}</strong><br>${days[dow]}<br><small>(${daysEn[dow]})</small>`;
    document.getElementById('cal-event-name').textContent = event;
    card?.classList.remove('hidden');
  }

  // Open current month by default when navigating to page
  document.addEventListener('bhakti-page-change', e => {
    if(e.detail === 'page-calendar') renderCalGrid(calYear, calMonth);
  });
}

