let MUH_DATA = null;
let MUH_CUR_TAB = 'vivah';

const MUH_LABELS = {
  vivah:    '💍 विवाह मुहूर्त',
  griha:    '🏠 गृह प्रवेश मुहूर्त',
  vehicle:  '🚗 वाहन खरीद मुहूर्त',
  property: '📋 संपत्ति खरीद मुहूर्त',
};

const HI_MONTHS_SHORT = ['','जन','फ़र','मार्च','अप्र','मई','जून','जुल','अग','सित','अक्त','नव','दिस'];

async function loadMuhData() {
  if(MUH_DATA) return true;
  try {
    const r = await fetch('data/muhurat.json');
    MUH_DATA = await r.json();
    return true;
  } catch(e) {
    console.warn('Muhurat JSON load failed:', e);
    return false;
  }
}

function renderMuhList(tab) {
  const list  = document.getElementById('muh-list');
  const title = document.getElementById('muh-tab-title');
  if(!list) return;

  if(!MUH_DATA || !MUH_DATA[tab]) {
    list.innerHTML = '<div class="mp-no-data">❌ डेटा उपलब्ध नहीं</div>';
    return;
  }

  if(title) title.textContent = (MUH_LABELS[tab] || tab) + ' 2026–27';

  const dates = MUH_DATA[tab];
  if(!dates.length) {
    list.innerHTML = '<div class="mp-no-data">कोई शुभ तिथि नहीं मिली</div>';
    return;
  }

  const today = new Date().toISOString().slice(0,10);
  const html = dates.map(d => {
    const isPast = d.date < today;
    if(isPast) return '';   // skip past dates

    const [y,m,day] = d.date.split('-');
    const monthName = HI_MONTHS_SHORT[parseInt(m)];
    const dayNum = parseInt(day);
    const timeStr = (d.muhurat_start && d.muhurat_end) ? `⏰ ${d.muhurat_start} — ${d.muhurat_end}` : '';
    const details = [d.tithi, d.nakshatra].filter(Boolean).join(' | ');

    return `<div class="muh-card">
      <div class="muh-cal-leaf">
        <div class="muh-cal-month">${monthName} ${y}</div>
        <div class="muh-cal-date">${dayNum}</div>
        <div class="muh-cal-day">${d.weekday || ''}</div>
      </div>
      <div class="muh-card-content">
        ${timeStr ? `<div class="muh-card-time">${timeStr}</div>` : ''}
        ${details ? `<div class="muh-card-detail">📿 ${details}</div>` : ''}
        <div class="muh-card-shubh">शुभ योग</div>
      </div>
    </div>`;
  }).join('');

  list.innerHTML = html || '<div class="mp-no-data">कोई आगामी शुभ तिथि नहीं मिली</div>';
}

function switchMuhTab(tab) {
  MUH_CUR_TAB = tab;
  document.querySelectorAll('.muh-tab').forEach(t => {
    t.classList.toggle('active', t.dataset.tab === tab);
  });
  renderMuhList(tab);
}

async function openMuhurat(tab) {
  MUH_CUR_TAB = tab || 'vivah';
  showPage('page-muhurat');
  const list = document.getElementById('muh-list');
  if(list) list.innerHTML = '<div class="mp-loading">⏳ लोड हो रहा है...</div>';
  const ok = await loadMuhData();
  if(ok) {
    // Set active tab
    document.querySelectorAll('.muh-tab').forEach(t => {
      t.classList.toggle('active', t.dataset.tab === MUH_CUR_TAB);
    });
    renderMuhList(MUH_CUR_TAB);
  } else {
    if(list) list.innerHTML = '<div class="mp-no-data">❌ डेटा लोड नहीं हो सका</div>';
  }
}

function initMuhuratPage() {
  // Tab clicks
  document.querySelectorAll('.muh-tab').forEach(tab => {
    tab.addEventListener('click', () => switchMuhTab(tab.dataset.tab));
  });

  // Home muhurat cards → open muhurat page with correct tab
  document.querySelectorAll('.muhurat-home-card').forEach(card => {
    card.addEventListener('click', () => {
      openMuhurat(card.dataset.muhuratType);
    });
  });

  // Home section link
  document.querySelectorAll('.home-section-link[data-page="page-muhurat"]').forEach(a => {
    a.addEventListener('click', () => openMuhurat('vivah'));
  });

  // Fill home card "next date" previews
  loadMuhData().then(ok => {
    if(!ok || !MUH_DATA) return;
    const today = new Date().toISOString().slice(0,10);
    const CARD_IDS = {vivah:'mhc-vivah-next', griha:'mhc-griha-next',
                      vehicle:'mhc-vehicle-next', property:'mhc-property-next'};
    for(const [tab, elId] of Object.entries(CARD_IDS)) {
      const el = document.getElementById(elId);
      if(!el) continue;
      const next = (MUH_DATA[tab] || []).find(d => d.date >= today);
      if(next) {
        const [y,m,day] = next.date.split('-');
        el.textContent = `अगला: ${parseInt(day)} ${HI_MONTHS_SHORT[parseInt(m)]}`;
      }
    }
  });
}

function showToast(msg){
  let t = $('app-toast');
  if(!t){ t = document.createElement('div'); t.id='app-toast';
    Object.assign(t.style,{position:'fixed',bottom:'75px',left:'50%',transform:'translateX(-50%)',background:'rgba(20,5,0,0.88)',color:'#fff',padding:'0.55rem 1.1rem',borderRadius:'20px',fontSize:'0.88rem',fontWeight:'600',zIndex:'999',transition:'opacity 0.3s',opacity:'0',whiteSpace:'nowrap',fontFamily:'inherit'});
    document.body.appendChild(t);
  }
  t.textContent = msg; t.style.opacity = '1';
  clearTimeout(t._t);
  t._t = setTimeout(()=>{ t.style.opacity='0'; }, 2400);
}

function showPage(id){
  // Hide floating mini players on all general pages
  const gMini = document.getElementById('glass-mini-player');
  const mPlayer = document.getElementById('mini-player');
  if (gMini && typeof isAudioPlaying !== 'undefined' && !isAudioPlaying) gMini.style.display = 'none';
  if (mPlayer) mPlayer.style.display = 'none';

  if (typeof window.updateCurvedBottomNav === 'function') {
    window.updateCurvedBottomNav(id);
  }

  if (id === 'page-epic-games' || id === 'page-reader' || id === 'page-3d-mandir') {
    const navEl = document.getElementById('curved-fluid-bottom-nav');
    if (navEl) navEl.classList.add('nav-hidden');
    document.querySelectorAll('.app-bottom-nav, .bottom-nav').forEach(el => el.classList.add('nav-hidden'));
  }

  if(!$(id)) return;
  if(id === 'page-profile' && typeof window.updateProfileUI === 'function') { window.updateProfileUI(); }
  if(id === 'page-chalisa' && typeof window.renderFullDrikChalisaPage === 'function') {
    window.renderFullDrikChalisaPage('all', '');
  }

  if(id === 'page-sundarkand' && typeof window.renderFullSundarkandPage === 'function') {
    window.renderFullSundarkandPage('all', '');
  }

  if(id === 'page-mantra' && typeof window.renderFullDrikMantraPage === 'function') {
    window.renderFullDrikMantraPage('all', '');
  }

  if(id === 'page-aarti' && typeof window.renderFullDrikAartiPage === 'function') {
    window.renderFullDrikAartiPage('all', '');
  }

  if(id === 'page-gita' && typeof window.renderFullGitaPage === 'function') {
    window.renderFullGitaPage('all', '');
  }

  document.querySelectorAll('.page').forEach(p => {
    p.classList.remove('active');
    p.style.display = 'none';
  });
  const activePageEl = $(id);
  if (activePageEl) {
    activePageEl.classList.add('active');
    activePageEl.style.display = 'block';
  }
  currentPage = id;
  window.currentPage = id;
  if (!window._appPageHistory) window._appPageHistory = ['page-home'];
  if (!window._isNavigatingBack && window._appPageHistory[window._appPageHistory.length - 1] !== id) {
    window._appPageHistory.push(id);
  }
  if (id === 'page-home' && typeof window.initVratGrids === 'function') {
    window.initVratGrids();
  }
  document.querySelectorAll('.bottom-nav-btn, .nav-item').forEach(b => b.classList.toggle('active', b.dataset.page === id));
  const titles = {
    'page-home':'भक्ति में लीन','page-bhajan':'भजन','page-aarti':'आरती',
    'page-mantra':'मंत्र','page-chalisa':'चालीसा','page-desh':'देश-भक्ति',
    'page-ramayana':'रामायण','page-profile':'प्रोफाइल','page-settings':'सेटिंग',
    'page-about':'हमारे बारे में','page-downloads':'मेरे डाउनलोड','page-reader':'पाठ',
    'page-calendar':'हिन्दी कैलेंडर','page-katha':'कथाएं & प्रवचन',
    'page-achievements':'उपलब्धियाँ','page-sundarkand':'श्री सुन्दरकाण्ड',
    'page-gita':'श्रीमद्भगवद्गीता',
  };
  const h = document.querySelector('.header-title');
  if(h && titles[id]) h.textContent = titles[id];
  window.scrollTo(0,0);
  // Notify calendar of page switch
  document.dispatchEvent(new CustomEvent('bhakti-page-change', { detail: id }));
}

