let readerBackPage = 'page-home';
let jaapMalaCount = 0;
let readerAudio = null;
let readerAudioLoop = false;
let readerPlaybackRates = [1.0, 1.25, 1.5, 0.8];
let currentRateIdx = 0;

const DEITY_LOTUS_MAP = {
  hanuman: 'assets/deity_hanuman.jpg',
  shiv: 'assets/deity_shiv.jpg',
  ganesh: 'assets/deity_ganesh.jpg',
  krishna: 'assets/deity_krishna.jpg',
  durga: 'assets/deity_durga.jpg',
  lakshmi: 'assets/deity_lakshmi.jpg',
  saraswati: 'assets/deity_saraswati.jpg',
  vishnu: 'assets/deity_vishnu.jpg',
  ram: 'assets/deity_ramayana.jpg',
  gayatri: 'assets/deity_saraswati.jpg',
  mahamrityunjaya: 'assets/deity_shiv.jpg',
  surya: 'assets/deity_vishwakarma.jpg'
};

function openReader(key, fromPage) {
  if (fromPage) readerBackPage = fromPage;
  
  let item = null;
  if (typeof key === 'string') {
    item = CONTENT[key] || { title: key, text: key };
    if (!item.deity) {
      if (key.includes('hanuman')) item.deity = 'श्री हनुमान जी';
      else if (key.includes('shiv')) item.deity = 'भगवान शिव';
      else if (key.includes('ganesh')) item.deity = 'भगवान श्री गणेश';
      else if (key.includes('durga')) item.deity = 'माँ दुर्गा';
      else if (key.includes('krishna')) item.deity = 'भगवान श्री कृष्ण';
      else if (key.includes('lakshmi')) item.deity = 'माँ लक्ष्मी';
      else if (key.includes('saraswati')) item.deity = 'माँ सरस्वती';
      else if (key.includes('vishnu')) item.deity = 'भगवान श्री विष्णु';
      else if (key.includes('ram')) item.deity = 'प्रभु श्री राम';
      else if (key.includes('gayatri')) item.deity = 'माँ गायत्री';
      else if (key.includes('mahamrityunjaya')) item.deity = 'महादेव शिव';
      else item.deity = 'सनातन';
    }
  } else if (typeof key === 'object') {
    item = key;
  }
  
  if (!item) return;

  // Set Back Button target
  const backBtn = document.querySelector('#page-reader .back-btn');
  if (backBtn) {
    backBtn.setAttribute('data-back', readerBackPage || 'page-home');
    backBtn.onclick = () => showPage(readerBackPage || 'page-home');
  }

  // 1. Set Title & Deity Image
  const titleEl = document.getElementById('reader-page-title');
  const aTitleEl = document.getElementById('reader-audio-title');
  const aSubEl = document.getElementById('reader-audio-sub');
  const imgEl = document.getElementById('reader-deity-img');
  
  const titleText = item.title || item.name || 'दिव्य पाठ';
  if (titleEl) titleEl.textContent = titleText;
  if (aTitleEl) aTitleEl.textContent = titleText;
  if (aSubEl) aSubEl.textContent = `${item.deity || 'सनातन'} • दिव्य पाठ व श्रवण`;
  
  // Find appropriate deity image
  let dImg = 'assets/deity_hanuman.jpg';
  const itemStr = (item.deity || item.title || item.name || (typeof key === 'string' ? key : '')).toLowerCase();
  for (let [k, v] of Object.entries(DEITY_LOTUS_MAP)) {
    if (itemStr.includes(k)) {
      dImg = v;
      break;
    }
  }
  if (imgEl) imgEl.src = dImg;

  // 2. Render Cosmic Verses
  const container = document.getElementById('reader-cosmic-content');
  if (container) {
    if (item.lines && Array.isArray(item.lines)) {
      container.innerHTML = item.lines.map((line, idx) => `
        <div class="cosmic-verse-card ${idx === 0 ? 'active-verse' : ''}" id="verse-${idx}">
          <div class="cosmic-verse-text">${line.hindi || line.text || line}</div>
          ${line.meaning ? `<div class="cosmic-verse-meaning">📖 <strong>भावार्थ:</strong> ${line.meaning}</div>` : ''}
        </div>
      `).join('');
    } else if (item.text || item.content) {
      const rawText = item.text || item.content;
      const paragraphs = rawText.split('\n\n');
      container.innerHTML = paragraphs.map((p, idx) => `
        <div class="cosmic-verse-card ${idx === 0 ? 'active-verse' : ''}">
          <div class="cosmic-verse-text">${p.replace(/\n/g, '<br>')}</div>
        </div>
      `).join('');
    } else {
      container.innerHTML = `
        <div class="cosmic-verse-card active-verse">
          <div class="cosmic-verse-text">॥ ${titleText} ॥<br><br>जय जय श्री सीताराम। जय जय हनुमान॥</div>
          <div class="cosmic-verse-meaning">प्रभु का नाम स्मरण समस्त कष्टों को हरने वाला और परम शांति प्रदान करने वाला है।</div>
        </div>
      `;
    }
  }

  // 3. Reset Jaap Mala
  jaapMalaCount = 0;
  updateJaapBadge();

  // 4. Setup Audio (Dual-Mode: Local MP3 or YouTube)
  const rMediaUrl = item.audio_url || item.audio || item.video_url;
  const readerAudioBar = document.querySelector('.cosmic-audio-bar');

  if (window.MediaRouter && window.MediaRouter.isYouTubeUrl(rMediaUrl)) {
    // Mode 2: YouTube in Reader
    if (readerAudioBar) readerAudioBar.style.display = 'none';
    window.MediaRouter.loadYouTubePlayer(rMediaUrl, 'reader-youtube-container', {
      title: titleText,
      deity: item.deity
    });
  } else if (rMediaUrl && rMediaUrl.trim() !== '') {
    // Mode 1: Local MP3
    if (window.MediaRouter) window.MediaRouter.destroyYouTubePlayer();
    if (readerAudioBar) readerAudioBar.style.display = '';
    if (!readerAudio) {
      readerAudio = new Audio();
      readerAudio.addEventListener('timeupdate', updateReaderTime);
      readerAudio.addEventListener('ended', () => {
        if (readerAudioLoop) {
          readerAudio.currentTime = 0;
          readerAudio.play();
          incrementJaapCounter();
        } else {
          const playBtn = document.getElementById('reader-cosmic-play');
          if (playBtn) playBtn.textContent = '▶';
        }
      });
    }
    readerAudio.src = rMediaUrl;
  } else {
    // Bind to AI Bhakti Singing & Chanting Player
    if (window.AiBhaktiPlayer) {
      window.AiBhaktiPlayer.loadContent(item);
    }
  }

  // Guaranteed synchronization with AI Bhakti Player
  if (window.AiBhaktiPlayer && typeof window.AiBhaktiPlayer.loadContent === 'function') {
    window.AiBhaktiPlayer.loadContent(item);
  }

  showPage('page-reader');
}

function updateReaderTime() {
  if (!readerAudio) return;
  const cur = readerAudio.currentTime || 0;
  const dur = readerAudio.duration || 225;
  const pct = (cur / dur) * 100;
  
  const curEl = document.getElementById('reader-cur-time');
  const totEl = document.getElementById('reader-tot-time');
  const seekEl = document.getElementById('reader-audio-seekbar');
  
  if (curEl) curEl.textContent = formatAudioTime(cur);
  if (totEl) totEl.textContent = formatAudioTime(dur);
  if (seekEl) seekEl.value = pct;
}

function toggleReaderAudioPlay() {
  const playBtn = document.getElementById('reader-cosmic-play');
  if (!readerAudio) {
    readerAudio = new Audio('https://ia800208.us.archive.org/21/items/ShreeHanumanChalisa_201602/Shree%20Hanuman%20Chalisa.mp3');
    readerAudio.addEventListener('timeupdate', updateReaderTime);
  }

  if (readerAudio.paused) {
    readerAudio.play().then(() => {
      if (playBtn) playBtn.textContent = '⏸';
      triggerFlowerShower();
      showToast('🎵 दिव्य पाठ प्रारंभ हुआ');
    }).catch(() => {
      if (playBtn) playBtn.textContent = '⏸';
    });
  } else {
    readerAudio.pause();
    if (playBtn) playBtn.textContent = '▶';
  }
}

function seekReaderAudio(val) {
  if (readerAudio && readerAudio.duration) {
    readerAudio.currentTime = (val / 100) * readerAudio.duration;
  }
}

function cycleAudioSpeed() {
  currentRateIdx = (currentRateIdx + 1) % readerPlaybackRates.length;
  const rate = readerPlaybackRates[currentRateIdx];
  if (readerAudio) readerAudio.playbackRate = rate;
  const btn = document.getElementById('reader-speed-btn');
  if (btn) btn.textContent = `${rate.toFixed(1)}x`;
  showToast(`⚡ ऑडियो गति: ${rate}x`);
}

function toggleReaderLoop() {
  readerAudioLoop = !readerAudioLoop;
  const btn = document.getElementById('reader-loop-btn');
  if (btn) {
    btn.style.background = readerAudioLoop ? 'linear-gradient(135deg, #EC4899 0%, #BE185D 100%)' : 'rgba(45, 18, 77, 0.8)';
  }
  showToast(readerAudioLoop ? '🔁 108 बार निरंतर जाप लूप चालू है' : '🔁 लूप बंद है');
}

function triggerFlowerShower() {
  const petals = ['🌸', '🌺', '🌼', '🪷', '✨', '💐'];
  const count = 18;
  for (let i = 0; i < count; i++) {
    const el = document.createElement('div');
    el.className = 'flower-particle';
    el.textContent = petals[Math.floor(Math.random() * petals.length)];
    el.style.left = `${Math.random() * 95}vw`;
    el.style.animationDuration = `${2 + Math.random() * 2}s`;
    el.style.animationDelay = `${Math.random() * 0.8}s`;
    el.style.fontSize = `${1.2 + Math.random() * 1}rem`;
    document.body.appendChild(el);
    setTimeout(() => el.remove(), 4000);
  }
  showToast('🌸 प्रभु चरणों में पुष्प वर्षा समर्पित!');
}

function incrementJaapCounter() {
  jaapMalaCount = (jaapMalaCount + 1) % 109;
  if (jaapMalaCount === 0) jaapMalaCount = 1;
  updateJaapBadge();
  if (jaapMalaCount === 108) {
    triggerFlowerShower();
    showToast('🎉 108 बार दिव्य महाजाप सम्पूर्ण! कोटि-कोटि पुण्य फल!');
  } else if (jaapMalaCount % 11 === 0) {
    showToast(`📿 ${jaapMalaCount} बार जाप पूर्ण!`);
  }
}

function updateJaapBadge() {
  const badge = document.getElementById('reader-jaap-count');
  if (badge) badge.textContent = `${jaapMalaCount}/108`;
}

function ringBell() {
  showToast('🔔 ॐ नमः शिवाय! मंदिर घंटी निनाद!');
  triggerFlowerShower();
}

function initReader() {
  document.querySelectorAll('.back-btn').forEach(btn => {
    btn.onclick = () => {
      const target = btn.getAttribute('data-back') || readerBackPage || 'page-home';
      showPage(target);
    };
  });
}

function buildDeityGrid(containerId, items, contentPrefix, fromPage) {
  const container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = '';
  items.forEach(d => {
    const card = document.createElement('button');
    card.className = 'deity-card';
    const imgHtml = d.img 
      ? `<img src="${d.img}" alt="${d.name}" class="deity-card-img" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'" /><div class="deity-card-emoji" style="display:none">${d.emoji || '🕉️'}</div>`
      : `<div class="deity-card-emoji">${d.emoji || '🕉️'}</div>`;
    
    card.innerHTML = `${imgHtml}<span class="deity-card-name">${d.name}</span>`;
    const contentKey = d.contentKey || (contentPrefix + '_' + d.id);
    card.addEventListener('click', () => { openReader(contentKey, fromPage); });
    container.appendChild(card);
  });
}

