// ══════════════════════════════════════════════════════
//  PANCHANG PAGE
// ══════════════════════════════════════════════════════

// Panchang type configs
const PANCHANG_CONFIGS = {
  month:    { file:'data/month_panchang.json',    label:'माह पंचांग',        lang:'Hindi' },
  tamil:    { file:'data/tamil_panchang.json',    label:'तमिल पंचांगम',     lang:'Tamil' },
  telugu:   { file:'data/telugu_panchang.json',   label:'तेलुगु पंचांगम',   lang:'Telugu' },
  kannada:  { file:'data/kannada_panchang.json',  label:'कन्नड़ पंचांग',    lang:'Kannada' },
  malayalam:{ file:'data/malayalam_panchang.json',label:'मलयालम पंचांगम',   lang:'Malayalam' },
  gujarati: { file:'data/gujarati_panchang.json', label:'गुजराती पंचांग',   lang:'Gujarati' },
  marathi:  { file:'data/marathi_panchang.json',  label:'मराठी पंचांग',     lang:'Marathi' },
  bengali:  { file:'data/bengali_panchang.json',  label:'बंगाली पंजिका',    lang:'Bengali' },
  odia:     { file:'data/odia_panchang.json',     label:'ओड़िया पंजी',      lang:'Odia' },
  nepali:   { file:'data/nepali_panchang.json',   label:'नेपाली पात्रो',    lang:'Nepali' },
  iskcon:   { file:'data/iskcon_panchang.json',   label:'ISKCON पंचांग',     lang:'ISKCON' },
  assamese: { file:'data/assamese_panchang.json', label:'असमिया पंजिका',    lang:'Assamese' },
};

// Per-type data cache
const MP_CACHE = {};
let MP_CUR_YEAR  = 2026;
let MP_CUR_MONTH = 8;
let MP_CUR_TYPE  = 'month';  // active panchang type

const MP_HINDI_MONTHS = {
  1:'जनवरी',2:'फरवरी',3:'मार्च',4:'अप्रैल',5:'मई',6:'जून',
  7:'जुलाई',8:'अगस्त',9:'सितंबर',10:'अक्टूबर',11:'नवंबर',12:'दिसंबर'
};

// Festivals lookup for panchang row highlight
const MP_FESTIVALS = (typeof FESTIVALS_2026 !== 'undefined' ? FESTIVALS_2026 : []).reduce((acc, f) => {
  if(f.date) acc[f.date] = f.name;
  return acc;
}, {});

async function loadMPData(type) {
  if(MP_CACHE[type]) return true;
  const cfg = PANCHANG_CONFIGS[type];
  if(!cfg) return false;
  try {
    const r = await fetch(cfg.file);
    MP_CACHE[type] = await r.json();
    return true;
  } catch(e) {
    console.warn(`Panchang JSON load failed (${type}):`, e);
    return false;
  }
}

function renderMPTable(type, year, month) {
  const key = `${year}-${month}`;
  const body        = document.getElementById('mp-table-body');
  const monthNameEl = document.getElementById('mp-month-name');
  const vikramEl    = document.getElementById('mp-vikram');
  const todayStrip  = document.getElementById('mp-today-strip');
  const todayInfo   = document.getElementById('mp-today-info');
  const headerTitle = document.getElementById('mp-header-title');

  if(!body) return;

  const cfg = PANCHANG_CONFIGS[type] || PANCHANG_CONFIGS['month'];
  const typeData = MP_CACHE[type];
  const monthData = typeData && typeData[key];

  // Update header with panchang type name
  if(headerTitle) headerTitle.textContent = cfg.label;

  if(!monthData || !monthData.days || monthData.days.length === 0) {
    body.innerHTML = `<div class="mp-no-data">📡 ${MP_HINDI_MONTHS[month]} ${year} का डेटा उपलब्ध नहीं है।<br><small>कृपया बाद में प्रयास करें</small></div>`;
    if(monthNameEl) monthNameEl.textContent = `${MP_HINDI_MONTHS[month]} ${year}`;
    return;
  }

  if(monthNameEl) monthNameEl.textContent = `${monthData.hindi_month || MP_HINDI_MONTHS[month]} ${year}`;
  if(vikramEl)    vikramEl.textContent = monthData.vikram_samvat || cfg.lang;

  const now  = new Date();
  const todayDay = now.getDate();
  const isCurrentMonth = (now.getFullYear() === year && now.getMonth()+1 === month);

  // Today strip
  if(isCurrentMonth) {
    const todayData = monthData.days.find(d => d.day === todayDay);
    if(todayData && todayStrip) {
      todayStrip.style.display = 'flex';
      if(todayInfo) todayInfo.textContent = `${todayDay} — ${todayData.paksha} ${todayData.tithi} | ${todayData.nakshatra || '—'} | ↑${todayData.sunrise} ↓${todayData.sunset}`;
    }
  } else {
    if(todayStrip) todayStrip.style.display = 'none';
  }

  // Build rows
  const rows = monthData.days.map(d => {
    const isSunday  = d.weekday === 'रविवार';
    const isToday   = isCurrentMonth && d.day === todayDay;
    const dateStr   = `${year}-${String(month).padStart(2,'0')}-${String(d.day).padStart(2,'0')}`;
    const festival  = MP_FESTIVALS[dateStr] || '';

    const pakshaClass = d.paksha === 'कृष्ण' ? 'mp-paksha-k' : 'mp-paksha-s';
    const pakshaShort = d.paksha === 'कृष्ण' ? '🌑' : '🌕';

    let rowClass = 'mp-row';
    if(isToday)  rowClass += ' mp-today-row';
    if(isSunday) rowClass += ' mp-sunday';
    if(festival) rowClass += ' mp-festival-row';

    return `<div class="${rowClass}">
      <div class="mp-td mp-col-date">${d.day}${isToday ? '<br><span style="font-size:0.5rem;color:hsl(33,100%,40%)">आज</span>' : ''}</div>
      <div class="mp-td mp-col-day">${d.weekday ? d.weekday.slice(0,3) : '—'}</div>
      <div class="mp-td mp-col-sun">${d.sunrise || '—'}</div>
      <div class="mp-td mp-col-sun">${d.sunset  || '—'}</div>
      <div class="mp-td">
        <span class="mp-tithi-pill">
          <span class="${pakshaClass}">${pakshaShort}</span>
          ${d.tithi || '—'}
        </span>
        ${festival ? `<span class="mp-festival-tag">🎉 ${festival}</span>` : ''}
      </div>
      <div class="mp-td">
        <span class="mp-nak-text">${d.nakshatra || '—'}</span>
      </div>
    </div>`;
  }).join('');

  body.innerHTML = rows || `<div class="mp-no-data">कोई डेटा नहीं मिला</div>`;

  // Scroll to today row
  if(isCurrentMonth) {
    setTimeout(() => {
      const todayRow = body.querySelector('.mp-today-row');
      if(todayRow) todayRow.scrollIntoView({behavior:'smooth', block:'center'});
    }, 150);
  }
}

async function openMonthPanchang(type, year, month) {
  MP_CUR_TYPE  = type || 'month';
  MP_CUR_YEAR  = year;
  MP_CUR_MONTH = month;

  showPage('page-month-panchang');

  const body = document.getElementById('mp-table-body');
  if(body) body.innerHTML = '<div class="mp-loading">⏳ लोड हो रहा है...</div>';

  const ok = await loadMPData(MP_CUR_TYPE);
  if(ok) {
    renderMPTable(MP_CUR_TYPE, year, month);
  } else {
    if(body) body.innerHTML = '<div class="mp-no-data">❌ डेटा लोड नहीं हो सका।</div>';
  }
}

function initPanchangPage() {
  const now = new Date();

  // Map panch-card IDs to panchang types
  const CARD_TO_TYPE = {
    'month':     'month',
    'hindi':     'month',
    'tamil':     'tamil',
    'telugu':    'telugu',
    'kannada':   'kannada',
    'malayalam': 'malayalam',
    'gujarati':  'gujarati',
    'marathi':   'marathi',
    'bengali':   'bengali',
    'odia':      'odia',
    'nepali':    'nepali',
    'iskcon':    'iskcon',
    'assamese':  'assamese',
  };

  document.querySelectorAll('.panch-card').forEach(card => {
    card.addEventListener('click', () => {
      const id   = card.dataset.panchId;
      const type = CARD_TO_TYPE[id];
      if(type) {
        openMonthPanchang(type, now.getFullYear(), now.getMonth()+1);
      } else {
        showToast(`📡 ${card.querySelector('.panch-card-name').textContent} — जल्द आ रहा है!`);
      }
    });
  });

  // Month navigation — keep current type
  document.getElementById('mp-prev-btn')?.addEventListener('click', () => {
    MP_CUR_MONTH--;
    if(MP_CUR_MONTH < 1) { MP_CUR_MONTH = 12; MP_CUR_YEAR--; }
    openMonthPanchang(MP_CUR_TYPE, MP_CUR_YEAR, MP_CUR_MONTH);
  });
  document.getElementById('mp-next-btn')?.addEventListener('click', () => {
    MP_CUR_MONTH++;
    if(MP_CUR_MONTH > 12) { MP_CUR_MONTH = 1; MP_CUR_YEAR++; }
    openMonthPanchang(MP_CUR_TYPE, MP_CUR_YEAR, MP_CUR_MONTH);
  });

  // Fill panchang page today-bar from home panchang widget
  const sync = (from, to) => {
    const src = document.getElementById(from);
    const dst = document.getElementById(to);
    if(src && dst) dst.textContent = src.textContent;
  };
  sync('panchang-tithi', 'pt-tithi');
  sync('p-nakshatra',    'pt-nakshatra');
  sync('p-paksha',       'pt-paksha');
}


function showToast(msg) {
  let toast = document.getElementById('bhakti-toast');
  if(!toast) {
    toast = document.createElement('div');
    toast.id = 'bhakti-toast';
    toast.style.cssText = `
      position:fixed; bottom:80px; left:50%; transform:translateX(-50%) translateY(20px);
      background:linear-gradient(135deg,hsl(33,100%,40%),hsl(10,80%,28%));
      color:#fff; padding:0.6rem 1.2rem; border-radius:24px;
      font-size:0.8rem; font-weight:700; font-family:inherit;
      box-shadow:0 4px 20px rgba(0,0,0,0.3);
      z-index:9999; opacity:0;
      transition:opacity 0.3s ease,transform 0.3s ease;
      white-space:nowrap; max-width:90vw; text-align:center;
    `;
    document.body.appendChild(toast);
  }
  toast.textContent = msg;
  toast.style.opacity = '1';
  toast.style.transform = 'translateX(-50%) translateY(0)';
  clearTimeout(toast._timer);
  toast._timer = setTimeout(() => {
    toast.style.opacity = '0';
    toast.style.transform = 'translateX(-50%) translateY(20px)';
  }, 2500);
}

