function initDrawer(){
  const drawer = $('side-drawer'), overlay = $('overlay'), ham = $('hamburger-btn');
  const open = ()=>{ drawer.classList.add('open'); overlay.classList.add('active'); };
  const close = ()=>{ drawer.classList.remove('open'); overlay.classList.remove('active'); };
  ham.addEventListener('click', open);
  overlay.addEventListener('click', close);
  const map = {'drawer-profile':'page-profile','drawer-downloads':'page-downloads','drawer-settings':'page-settings','drawer-about':'page-about'};
  Object.entries(map).forEach(([id,pg])=>{ $(id)?.addEventListener('click',()=>{ close(); showPage(pg); }); });
  $('drawer-upload')?.addEventListener('click',()=>{ close(); showToast('अपलोड फीचर जल्द आएगा!'); });
  $('drawer-rate')?.addEventListener('click',()=>{ close(); openModal('rate-modal'); });
}

