// ══════════════════════════════════════════════════════
function initStarRating(){
  let sel = 0;
  document.querySelectorAll('.star').forEach(s=>{
    s.addEventListener('click',()=>{ sel=+s.dataset.val; document.querySelectorAll('.star').forEach(x=>x.classList.toggle('lit',+x.dataset.val<=sel)); });
  });
  $('rate-submit')?.addEventListener('click',()=>{ if(sel>0){ closeModal('rate-modal'); showToast(`${sel} ⭐ रेटिंग के लिए धन्यवाद!`); } else showToast('कृपया रेटिंग चुनें'); });
}

// ══════════════════════════════════════════════════════
//  AUTH
// ══════════════════════════════════════════════════════
function getUser(){ return JSON.parse(localStorage.getItem('bhakti_user')||'null'); }
function setUser(u){ localStorage.setItem('bhakti_user',JSON.stringify(u)); }
function updateProfileUI(){
  const u = getUser();
  const nameEl=$('profile-name'), emailEl=$('profile-email'), avatarEl=$('profile-avatar');
  const lb=$('profile-login-btn'), lob=$('profile-logout-btn');
  if(u){
    if(nameEl) nameEl.textContent = u.name||u.email;
    if(emailEl) emailEl.textContent = u.email;
    if(avatarEl) avatarEl.textContent = (u.name||u.email)[0].toUpperCase();
    lb?.classList.add('hidden'); lob?.classList.remove('hidden');
  } else {
    if(nameEl) nameEl.textContent='अतिथि उपयोगकर्ता';
    if(emailEl) emailEl.textContent='';
    if(avatarEl) avatarEl.textContent='👤';
    lb?.classList.remove('hidden'); lob?.classList.add('hidden');
  }
  updateFavCount();
}
function initAuth(){
  $('profile-login-btn')?.addEventListener('click',()=>openModal('login-modal'));
  $('profile-logout-btn')?.addEventListener('click',()=>{ localStorage.removeItem('bhakti_user'); updateProfileUI(); showToast('लॉग‑आउट सफल'); });
  $('signup-submit')?.addEventListener('click',()=>{
    const n=$('signup-name')?.value.trim(), e=$('signup-email')?.value.trim(), p=$('signup-password')?.value;
    if(!e||!p){ showToast('ई‑मेल व पासवर्ड आवश्यक'); return; }
    const users=JSON.parse(localStorage.getItem('bhakti_users')||'[]');
    if(users.find(u=>u.email===e)){ showToast('ई‑मेल पहले से पंजीकृत'); return; }
    const u={name:n,email:e,pwd:p}; users.push(u); localStorage.setItem('bhakti_users',JSON.stringify(users));
    setUser(u); closeModal('signup-modal'); updateProfileUI(); showToast(`जय श्री राम! स्वागत है ${n||e} 🙏`);
  });
  $('login-submit')?.addEventListener('click',()=>{
    const e=$('login-email')?.value.trim(), p=$('login-password')?.value;
    const users=JSON.parse(localStorage.getItem('bhakti_users')||'[]');
    const u=users.find(x=>x.email===e&&x.pwd===p);
    if(!u){ showToast('ग़लत ई‑मेल या पासवर्ड'); return; }
    setUser(u); closeModal('login-modal'); updateProfileUI(); showToast(`जय श्री राम! नमस्ते ${u.name||u.email} 🙏`);
  });
  updateProfileUI();
}

// ══════════════════════════════════════════════════════
//  VERSES & MANTRAS (Home)
// ══════════════════════════════════════════════════════
function initDeityFilter(){
  $('deity-select')?.addEventListener('change',e=>{ currentDeity=e.target.value; verseIndex=0; mantraIndex=0; renderVerse(); renderMantra(); });
}
function getFiltered(arr){ return currentDeity==='all'?arr:arr.filter(v=>v.deity===currentDeity); }
function renderVerse(){
  const el=$('verse-text'); if(!el) return;
  const f=getFiltered(versesData); if(!f.length){ el.textContent='कोई श्लोक उपलब्ध नहीं।'; return; }
  verseIndex=((verseIndex%f.length)+f.length)%f.length;
  el.textContent=f[verseIndex].text;
}
function renderMantra(){
  const el=$('mantra-text'); if(!el) return;
  const f=getFiltered(mantrasData); if(!f.length){ el.textContent='कोई मंत्र उपलब्ध नहीं।'; return; }
  mantraIndex=((mantraIndex%f.length)+f.length)%f.length;
  el.textContent=f[mantraIndex].text;
}
async function loadHomeData(){
  const fetchJ=async(p)=>{ try{ const r=await fetch(p); return r.ok?await r.json():null; }catch(e){ return null; } };
  const vd=await fetchJ('data/verses.json'); versesData=vd?.verses?.length?vd.verses:FALLBACK_VERSES;
  const md=await fetchJ('data/mantras.json'); mantrasData=md?.mantras?.length?md.mantras:FALLBACK_MANTRAS;
  const d=new Date(); const dy=Math.floor((d-new Date(d.getFullYear(),0,0))/86400000);
  verseIndex=dy%versesData.length; mantraIndex=dy%mantrasData.length;
  renderVerse(); renderMantra();
}
function initRefreshButtons(){
  $('verse-refresh-btn')?.addEventListener('click',()=>{ verseIndex++; renderVerse(); });
  $('mantra-refresh-btn')?.addEventListener('click',()=>{ mantraIndex++; renderMantra(); });
}

// ══════════════════════════════════════════════════════
//  DARK MODE & FONT SIZE
// ══════════════════════════════════════════════════════
function initSettings(){
  const dm=$('dark-mode-toggle');
  if(dm){ dm.checked=localStorage.getItem('bhakti_dark')==='true'; document.body.classList.toggle('dark-mode',dm.checked); dm.addEventListener('change',()=>{ document.body.classList.toggle('dark-mode',dm.checked); localStorage.setItem('bhakti_dark',dm.checked); }); }
  const fs=$('font-size-select');
  if(fs){ const sv=localStorage.getItem('bhakti_font')||'1'; fs.value=sv; document.documentElement.style.setProperty('--reader-font',sv+'rem'); fs.addEventListener('change',()=>{ document.documentElement.style.setProperty('--reader-font',fs.value+'rem'); localStorage.setItem('bhakti_font',fs.value); }); }
}

// ══════════════════════════════════════════════════════
//  PWA
// ══════════════════════════════════════════════════════
let deferredPrompt=null;
function initPWA(){
  if('serviceWorker' in navigator){ navigator.serviceWorker.register('service-worker.js').catch(()=>{}); }
  window.addEventListener('beforeinstallprompt',e=>{ e.preventDefault(); deferredPrompt=e; const b=$('drawer-install'); if(b) b.style.display='flex'; });
  $('drawer-install')?.addEventListener('click',async()=>{ if(!deferredPrompt) return; deferredPrompt.prompt(); const{outcome}=await deferredPrompt.userChoice; if(outcome==='accepted') showToast('ऐप इंस्टॉल हो रहा है 🙏'); deferredPrompt=null; });
}

