//  KATHA / PODCAST
// ══════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════
//   🎵 ULTRA-MODERN GLASSMORPHISM AUDIO ENGINE
// ══════════════════════════════════════════════════════

let currentKathaIdx = 0;
let isAudioPlaying = false;
let isAudioShuffled = false;
let isAudioRepeated = false;
let isLyricsOpen = false;
let audioPlayerObj = null;

const KATHA_PLAYLIST = [
  {
    id: 1,
    title: 'बालकाण्ड - श्री राम जन्म',
    deity: 'श्री रामचरितमानस',
    sub: 'गोस्वामी तुलसीदास जी • भक्ति रस',
    img: 'assets/deity_ramayana.jpg',
    src: 'assets/audio/katha_ramayana.mp3',
    lyrics: `॥ श्री रामचरितमानस - बालकाण्ड ॥\n\nभए प्रगट कृपाला दीनदयाला कौसल्या हितकारी।\nहरषित महतारी मुनि मन हारी अद्भुत रूप बिचारी॥\n\nलोचन अभिरामा तनु घनस्यामा निज आयुध भुज चारी।\nभूषन बनमाला नयन बिसाला सोभासिंधु खरारी॥`
  },
  {
    id: 2,
    title: 'श्री हनुमान चालीसा (दिव्य पाठ)',
    deity: 'श्री हनुमान जी',
    sub: 'महावीर बजरंगबली • संकटमोचन',
    img: 'assets/deity_hanuman.jpg',
    src: 'assets/audio/katha_hanuman.mp3',
    lyrics: `॥ श्री हनुमान चालीसा ॥\n\nश्रीगुरु चरन सरोज रज निज मनु मुकुरु सुधारि।\nबरनउँ रघुबर बिमल जसु जो दायकु फल चारि॥\n\nबुद्धिहीन तनु जानिके सुमिरौ पवन-कुमार।\nबल बुधि बिद्या देहु मोहिं हरहु कलेस बिकार॥\n\nजय हनुमान ज्ञान गुन सागर।\nजय कपीस तिहुँ लोक उजागर॥`
  },
  {
    id: 3,
    title: 'शिव ताण्डव स्तोत्रम्',
    deity: 'भगवान शिव',
    sub: 'रावण कृत • महा शक्ति स्तोत्र',
    img: 'assets/deity_shiv.jpg',
    src: 'assets/audio/katha_hanuman.mp3',
    lyrics: `॥ शिव ताण्डव स्तोत्रम् ॥\n\nजटाटवीगलज्जलप्रवाहपावितस्थले\nगलेऽवलम्ब्य लम्बितां भुजङ्गतुङ्गमालिकाम्।\nडमड्डमड्डमड्डमन्निनादवड्डमर्वयं\nचकार चण्डताण्डवं तनोतु नः शिवः शिवम्॥`
  },
  {
    id: 4,
    title: 'श्रीमद्भगवद्गीता - अध्याय 2',
    deity: 'श्री कृष्ण',
    sub: 'सांख्य योग • दिव्य उपदेश',
    img: 'assets/deity_krishna.jpg',
    src: 'assets/audio/katha_ramayana.mp3',
    lyrics: `॥ श्रीमद्भगवद्गीता - द्वितीयोऽध्यायः ॥\n\nकर्मण्येवाधिकारस्ते मा फलेषु कदाचन।\nमा कर्मफलहेतुर्भूर्मा ते सङ्गोऽस्त्वकर्मणि॥\n\nयोगस्थः कुरु कर्माणि सङ्गं त्यक्त्वा धनञ्जय।\nसिद्ध्यसिद्ध्योः समो भूत्वा समत्वं योग उच्यते॥`
  }
];

function initKatha() {
  if (!audioPlayerObj) {
    audioPlayerObj = new Audio();
    audioPlayerObj.src = KATHA_PLAYLIST[currentKathaIdx].src;
    
    audioPlayerObj.addEventListener('timeupdate', () => {
      const cur = audioPlayerObj.currentTime || 0;
      const dur = audioPlayerObj.duration || 225;
      const pct = (cur / dur) * 100;
      
      const curStr = formatAudioTime(cur);
      const durStr = formatAudioTime(dur);
      
      const miniTime = document.getElementById('glass-mini-time');
      if (miniTime) miniTime.textContent = `${curStr} / ${durStr}`;
      
      const mCur = document.getElementById('glass-modal-cur-time');
      if (mCur) mCur.textContent = curStr;
      
      const mTot = document.getElementById('glass-modal-tot-time');
      if (mTot) mTot.textContent = durStr;
      
      const seek = document.getElementById('glass-modal-seekbar');
      if (seek) seek.value = pct;
    });

    audioPlayerObj.addEventListener('ended', () => {
      if (isAudioRepeated) {
        audioPlayerObj.currentTime = 0;
        audioPlayerObj.play();
      } else {
        nextTrack();
      }
    });
  }
  
  updatePlayerUI();
}

function formatAudioTime(sec) {
  if (isNaN(sec) || sec === 0) return '00:00';
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m < 10 ? '0' : ''}${m}:${s < 10 ? '0' : ''}${s}`;
}

function updatePlayerUI() {
  const track = KATHA_PLAYLIST[currentKathaIdx];
  if (!track) return;
  
  // Mini Player
  const miniTitle = document.getElementById('glass-mini-title');
  if (miniTitle) miniTitle.textContent = track.title;
  
  const miniDeity = document.getElementById('glass-mini-deity');
  if (miniDeity) miniDeity.textContent = track.deity;
  
  const miniCover = document.getElementById('glass-mini-cover');
  if (miniCover) {
    miniCover.src = track.img;
    if (isAudioPlaying) miniCover.classList.add('playing');
    else miniCover.classList.remove('playing');
  }
  
  const miniPlayBtn = document.getElementById('glass-mini-play-btn');
  if (miniPlayBtn) miniPlayBtn.textContent = isAudioPlaying ? '⏸' : '▶';

  // Full Modal Player
  const mTitle = document.getElementById('glass-modal-title');
  if (mTitle) mTitle.textContent = track.title;
  
  const mSub = document.getElementById('glass-modal-sub');
  if (mSub) mSub.textContent = track.sub;
  
  const mImg = document.getElementById('glass-modal-img');
  if (mImg) {
    mImg.src = track.img;
    if (isAudioPlaying) mImg.classList.add('playing');
    else mImg.classList.remove('playing');
  }
  
  const mPlayBtn = document.getElementById('glass-modal-play-btn');
  if (mPlayBtn) mPlayBtn.textContent = isAudioPlaying ? '⏸' : '▶';

  // Lyrics
  const lyrContent = document.getElementById('glass-lyrics-content');
  if (lyrContent && track.lyrics) {
    lyrContent.innerHTML = `<p style="margin:0; font-weight:700; color:var(--maroon-deep); line-height:1.8;">${track.lyrics.replace(/\n/g, '<br>')}</p>`;
  }
}

function playKatha(idx) {
  if (idx !== undefined && idx >= 0 && idx < KATHA_PLAYLIST.length) {
    currentKathaIdx = idx;
    if (audioPlayerObj) {
      audioPlayerObj.src = KATHA_PLAYLIST[currentKathaIdx].src;
    }
  }
  
  if (!audioPlayerObj) initKatha();
  
  audioPlayerObj.play().then(() => {
    isAudioPlaying = true;
    updatePlayerUI();
    showToast(`🎵 बजा रहे हैं: ${KATHA_PLAYLIST[currentKathaIdx].title}`);
  }).catch(e => {
    console.warn("Audio play blocked or offline:", e);
    isAudioPlaying = true;
    updatePlayerUI();
  });
}

function togglePlayKatha() {
  if (!audioPlayerObj) initKatha();
  
  if (isAudioPlaying) {
    audioPlayerObj.pause();
    isAudioPlaying = false;
  } else {
    audioPlayerObj.play().catch(() => {});
    isAudioPlaying = true;
  }
  updatePlayerUI();
}

function nextTrack() {
  if (isAudioShuffled) {
    currentKathaIdx = Math.floor(Math.random() * KATHA_PLAYLIST.length);
  } else {
    currentKathaIdx = (currentKathaIdx + 1) % KATHA_PLAYLIST.length;
  }
  playKatha(currentKathaIdx);
}

function prevTrack() {
  currentKathaIdx = (currentKathaIdx - 1 + KATHA_PLAYLIST.length) % KATHA_PLAYLIST.length;
  playKatha(currentKathaIdx);
}

function toggleShuffle() {
  isAudioShuffled = !isAudioShuffled;
  const btn = document.getElementById('glass-shuffle-btn');
  if (btn) {
    btn.style.background = isAudioShuffled ? 'var(--gold-gradient)' : 'rgba(255,255,255,0.6)';
  }
  showToast(isAudioShuffled ? '🔀 शफल चालू है' : '🔀 शफल बंद है');
}

function toggleRepeat() {
  isAudioRepeated = !isAudioRepeated;
  const btn = document.getElementById('glass-repeat-btn');
  if (btn) {
    btn.style.background = isAudioRepeated ? 'var(--gold-gradient)' : 'rgba(255,255,255,0.6)';
  }
  showToast(isAudioRepeated ? '🔁 दोहराव (Repeat) चालू है' : '🔁 दोहराव बंद है');
}

function seekAudio(val) {
  if (audioPlayerObj && audioPlayerObj.duration) {
    audioPlayerObj.currentTime = (val / 100) * audioPlayerObj.duration;
  }
}

function openGlassPlayer() {
  const modal = document.getElementById('glass-full-player-modal');
  if (modal) {
    modal.classList.add('open');
    modal.style.display = 'flex';
    modal.style.opacity = '1';
    modal.style.pointerEvents = 'auto';
    modal.style.transform = 'translateY(0)';
  }
}

function closeGlassPlayer() {
  const modal = document.getElementById('glass-full-player-modal');
  if (modal) {
    modal.classList.remove('open');
    modal.style.display = 'none';
    modal.style.opacity = '0';
    modal.style.pointerEvents = 'none';
    modal.style.transform = 'translateY(100%)';
  }
  if (window.MediaRouter && window.MediaRouter.activeMode === 'youtube') {
    window.MediaRouter.destroyYouTubePlayer();
  }
}

function toggleLyricsDrawer() {
  isLyricsOpen = !isLyricsOpen;
  const content = document.getElementById('glass-lyrics-content');
  const txt = document.getElementById('glass-lyrics-tab-text');
  if (content) {
    content.style.display = isLyricsOpen ? 'block' : 'none';
  }
  if (txt) {
    txt.textContent = isLyricsOpen ? 'पाठ एवं भावार्थ छिपाएं (Lyrics) ⌄' : 'पाठ एवं भावार्थ देखें (Lyrics) ⌃';
  }
}

function toggleFavCurrent() {
  const favBtn1 = document.getElementById('glass-mini-fav');
  const favBtn2 = document.getElementById('glass-modal-fav');
  const isFav = favBtn1 && favBtn1.textContent === '❤️';
  const newIcon = isFav ? '🤍' : '❤️';
  if (favBtn1) favBtn1.textContent = newIcon;
  if (favBtn2) favBtn2.textContent = newIcon;
  showToast(isFav ? '🤍 पसंदीदा से हटाया गया' : '❤️ पसंदीदा में जोड़ा गया');
}

function playAudioFromVerse() {
  openGlassPlayer();
  playKatha(3); // Bhagavad Gita track
}

// ══════════════════════════════════════════════════════
//   📊 DAILY SADHANA PROGRESS & WEEKLY TRACKER
// ══════════════════════════════════════════════════════

let sadhanaTasks = [true, false, true, false];

function updateSadhanaProgress() {
  const completed = sadhanaTasks.filter(t => t).length;
  const total = sadhanaTasks.length;
  const pct = Math.round((completed / total) * 100);
  
  const pctText = document.getElementById('gauge-percent-text');
  if (pctText) pctText.textContent = `${pct}%`;
  
  const taskCount = document.getElementById('gauge-task-count');
  if (taskCount) taskCount.textContent = `${completed}/${total} कार्य पूरे हुए`;
  
  const arc = document.getElementById('gauge-progress-arc');
  if (arc) {
    // 204 is total circumference arc
    const offset = 204 - (204 * (pct / 100));
    arc.style.strokeDashoffset = offset;
  }
  
  const statusBadge = document.getElementById('gauge-status-badge');
  if (statusBadge) {
    if (pct === 100) statusBadge.textContent = '🎉 सम्पूर्ण साधना!';
    else if (pct >= 50) statusBadge.textContent = '🌟 शानदार प्रयास!';
    else statusBadge.textContent = '🌿 साधना प्रारंभ करें';
  }

  const timelineCount = document.getElementById('sadhana-timeline-count');
  if (timelineCount) timelineCount.textContent = `${completed} / ${total} पूर्ण`;
}

function toggleTask(idx) {
  if (idx >= 0 && idx < sadhanaTasks.length) {
    sadhanaTasks[idx] = !sadhanaTasks[idx];
    const badge = document.getElementById(`task-badge-${idx}`);
    if (badge) {
      if (sadhanaTasks[idx]) {
        badge.className = 'timeline-status-badge done';
        badge.textContent = 'Done ✓';
      } else {
        badge.className = 'timeline-status-badge start';
        badge.textContent = 'Start';
      }
    }
    updateSadhanaProgress();
  }
}

function toggleDayDone(dayIdx) {
  const el = document.getElementById(`day-${dayIdx}`);
  if (el) {
    el.classList.toggle('done');
    showToast('📅 दैनिक साधना अपडेट हो गई!');
  }
}

