//   2026 PRADOSHAM DATES RENDERER (Sanatan Panchang - IMAGE 1 PARITY)
// ══════════════════════════════════════════════════════
function renderDrikPradosh(containerId) {
  const c = document.getElementById(containerId);
  if (!c) return;

  let monthsHtml = PRADOSHAM_DATES_2026.map(mGroup => {
    let rowsHtml = mGroup.items.map(item => {
      const highlightClass = item.isHighlight ? 'dp-row-highlight' : '';
      const moonSvg = getDrikMoonSvg(item.moon);

      return `
        <div class="dp-row-item ${highlightClass}">
          <div class="dp-col-img-wrap" onclick="openPradoshKathaModal('${item.name}')" style="cursor:pointer;" title="${item.name} कथा एवं महत्व देखें">
            <img class="dp-deity-img" src="${item.img}" alt="${item.name}" onerror="this.src='assets/pradosha_shiva_parvati_kailash.jpg'">
          </div>
          <div class="dp-col-date-block">
            <div class="dp-col-date">${item.date}</div>
            <div class="dp-subnames-list">
              <a class="dp-subname-link" href="javascript:void(0);" onclick="openPradoshKathaModal('${item.name}')" title="${item.name} कथा एवं महत्व देखें">${item.name}</a>
              <div class="dp-muhurat-time" style="color:#111827; font-weight:600; font-size:0.88rem; margin-top:2px;">
                ${item.muhurat.replace('to', '<span style="color:#6B7280; font-weight:400;">to</span>')}
              </div>
            </div>
          </div>
          <div class="dp-col-moon-block">
            ${moonSvg}
            <div class="dp-paksha-label" style="font-size:0.8rem; color:#4B5563; font-weight:600; margin-top:3px; white-space:nowrap;">${item.duration}</div>
          </div>
          <div class="dp-col-tithi-block">
            <div class="dp-col-tithi-title">${item.tithi}</div>
            <div class="dp-col-timing-line">${item.begins}</div>
            <div class="dp-col-timing-line">${item.ends}</div>
          </div>
        </div>
      `;
    }).join('');

    return `
      <div class="dp-month-section">
        <div class="dp-month-banner">${mGroup.monthName}</div>
        ${rowsHtml}
      </div>
    `;
  }).join('');

  c.innerHTML = `
    <div class="dp-calendar-card">
      <div class="dp-header-bar">
        <div class="dp-header-left">
          <div class="dp-header-title">2026 Pradosham Dates</div>
          <div class="dp-header-samvat">[2082 - 2083] Vikrama Samvata</div>
        </div>
        <button class="dp-katha-btn" onclick="openPradoshKathaModal('सम्पूर्ण प्रदोष व्रत')">
          <span class="dp-katha-icon">📖</span> Vrat Katha Pradosha
        </button>
      </div>
      <div class="dp-rows-container">
        ${monthsHtml}
      </div>
      <div class="dp-calendar-footer">
        <strong>Notes:</strong> All timings are represented in 12-hour notation in local time of <strong>New Delhi, India</strong> with DST adjustment (if applicable).<br>Hours which are past midnight are suffixed with next day date. In Panchang day starts and ends with sunrise.
      </div>
    </div>

    <!-- 🔱 2026 PRADOSHAM DAYS EDUCATIONAL & SPIRITUAL GUIDE CARD (Sanatan Panchang) 🔱 -->
    <div class="dp-calendar-card dp-pradosh-guide-card" style="margin-top:20px; padding:22px; background:#FFFDF9; border:1px solid #FDE68A; border-radius:12px; box-shadow:0 4px 14px rgba(0,0,0,0.05);">
      
      <!-- 1. 2026 Pradosh Days or Pradosham Dates -->
      <div style="border-bottom:2px solid #FDE68A; padding-bottom:14px; margin-bottom:18px;">
        <h3 style="color:#7C2D12; font-size:1.35rem; font-weight:700; margin:0 0 6px 0; display:flex; align-items:center; gap:8px;">
          <span>🔱</span> 2026 Pradosh Days or Pradosham Dates
        </h3>
        <div style="color:#B45309; font-size:0.95rem; font-weight:600; margin-bottom:12px;">
          प्रदोष व्रत महिमा, त्रयोदशी तिथि एवं वार अनुसार प्रकार
        </div>

        <div style="display:flex; flex-wrap:wrap; gap:16px; align-items:flex-start; margin-bottom:12px;">
          <div style="flex:0 0 140px; max-width:160px;">
            <img src="assets/pradosh_vrat_banner.jpg" alt="Pradosham Vratam" style="width:100%; border-radius:10px; border:2px solid #D97706; box-shadow:0 3px 8px rgba(0,0,0,0.12);" onerror="this.src='assets/pradosha_shiva_parvati_kailash.jpg'">
          </div>
          <div style="flex:1; min-width:240px;">
            <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
              Pradosh Vrat, which is also known as <strong>Pradosham</strong> in South India, is observed to seek blessings of <a href="javascript:void(0);" onclick="openPradoshKathaModal('सम्पूर्ण प्रदोष व्रत')" style="color:#B45309; font-weight:600; text-decoration:underline;">Lord Shiva</a>.
            </p>
            <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
              Pradosh Vrat is observed on both Trayodashi Tithis, i.e. Shukla Paksha Trayodashi and Krishna Paksha Trayodashi, in lunar month. Some people distinguish between Shukla and Krishna Paksha Pradosham.
            </p>
            <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
              When Pradosham day falls on Monday it is called <strong>Soma Pradosham</strong>, on Tuesday it is called <strong>Bhauma Pradosham</strong> and on Saturday it is called as <strong>Shani Pradosham</strong>.
            </p>
          </div>
        </div>

        <div style="background:rgba(254, 243, 199, 0.4); padding:10px 14px; border-radius:8px; font-size:0.9rem; color:#78350F; line-height:1.6; border:1px dashed #F59E0B;">
          <strong>हिन्दी भावार्थ:</strong> प्रदोष व्रत (दक्षिण भारत में प्रदोषम) भगवान शिव और माता पार्वती की कृपा प्राप्त करने हेतु रखा जाता है। यह व्रत प्रत्येक माह के दोनों पक्षों (शुक्ल पक्ष व कृष्ण पक्ष) की त्रयोदशी तिथि को होता है। सोमवार को पड़ने पर <strong>सोम प्रदोष</strong>, मंगलवार को <strong>भौम प्रदोष</strong> तथा शनिवार को <strong>शनि प्रदोष</strong> कहलाता है।
        </div>
      </div>

      <!-- 2. Pradosh Vrat, Pradosham -->
      <div style="background:#FEF3C7; border-left:4px solid #D97706; padding:16px; border-radius:0 10px 10px 0; margin-bottom:18px;">
        <h4 style="color:#92400E; font-size:1.18rem; font-weight:700; margin:0 0 10px 0; display:flex; align-items:center; gap:8px;">
          <span>⏳</span> Pradosh Vrat, Pradosham (प्रदोष काल एवं शिव पूजन मुहूर्त)
        </h4>
        <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
          For Pradosham Vrat, day is fixed when Trayodashi Tithi falls during Pradosh Kaal which starts after Sunset. The time window after Sunset when Trayodashi Tithi and Pradosh time overlaps is auspicious for Shiva Puja. <strong>Sanatan Panchang.com</strong> lists this time for all Pradosham and this time should be preferred for doing Shiva Puja.
        </p>
        <div style="background:#FFFFFF; padding:10px 12px; border-radius:6px; font-size:0.88rem; color:#78350F; line-height:1.55;">
          <strong>प्रदोष काल समय:</strong> सूर्यास्त के पश्चात लगभग 2 घड़ी (2 घण्टे 24 मिनट) का समय प्रदोष काल कहलाता है। जिस दिन सूर्यास्त के समय त्रयोदशी तिथि व्याप्त हो, उसी दिन प्रदोष व्रत रखा जाता है। जब त्रयोदशी और प्रदोष काल एक साथ होते हैं, वही समय शिव पूजा हेतु सर्वश्रेष्ठ व शास्त्रोक्त होता है।
        </div>
      </div>

      <!-- 3. Location based Pradosham Days -->
      <div style="background:#EFF6FF; border-left:4px solid #3B82F6; padding:16px; border-radius:0 10px 10px 0; margin-bottom:18px;">
        <h4 style="color:#1E40AF; font-size:1.18rem; font-weight:700; margin:0 0 10px 0; display:flex; align-items:center; gap:8px;">
          <span>📍</span> Location based Pradosham Days (स्थान भेद से प्रदोष व्रत)
        </h4>
        <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
          It is important to understand that fasting day for Pradosham might differ for two cities even if those cities are within same Indian state. Fasting for Pradosham depends on sunset time and it is observed when Trayodashi Tithi prevails after sunset. Hence Pradosham fasting might be observed on Dwadashi Tithi i.e. one day before Trayodashi Tithi. As Sunset time is different for all cities, it is important to refer Hindu calendar like this website which lists location based Pradosham days. As generating location based dates are time consuming most sources ignore this fact and publish single list for all cities.
        </p>
        <div style="background:#FFFFFF; padding:10px 12px; border-radius:6px; font-size:0.88rem; color:#1E3A8A; line-height:1.55;">
          <strong>स्थान भेद का कारण:</strong> प्रत्येक नगर में सूर्यास्त का समय अलग-अलग होता है। प्रदोष व्रत सूर्यास्त के समय त्रयोदशी होने पर निर्भर करता है। अतः एक ही राज्य के दो शहरों में प्रदोष व्रत के दिन में भेद हो सकता है। यह पंचांग प्रत्येक स्थान के स्थानीय सूर्यास्त को ध्यान में रखकर सटीक तिथियाँ प्रस्तुत करता है।
        </div>
      </div>

      <!-- 4. Ekadashi and Pradosh on consecutive days -->
      <div style="background:#F0FDF4; border-left:4px solid #10B981; padding:16px; border-radius:0 10px 10px 0;">
        <h4 style="color:#065F46; font-size:1.18rem; font-weight:700; margin:0 0 10px 0; display:flex; align-items:center; gap:8px;">
          <span>🌙</span> Ekadashi and Pradosh on consecutive days (लगातार दो दिन एकादशी व प्रदोष व्रत)
        </h4>
        <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
          Many people observe Ekadashi Vrat as well as <a href="javascript:void(0);" onclick="openVratPage('pradosham')" style="color:#059669; font-weight:600; text-decoration:underline;">Pradosh Vrat</a>. Usually there is a gap of single day between Ekadashi and Pradosh fasting. However, many times they are observed on two consecutive days. Many devotees want to know how to break Ekadashi fast on the next day when Pradosh is getting observed on the same day. It is suggested to do symbolic Ekadashi Parana with only water and continue the Pradosh without actually breaking the fast. Although seems difficult but it is quite normal in Hinduism to fast on two consecutive days.
        </p>
        <div style="background:#FFFFFF; padding:10px 12px; border-radius:6px; font-size:0.88rem; color:#047857; line-height:1.55;">
          <strong>पारणा का नियम:</strong> यदि एकादशी के अगले दिन ही प्रदोष व्रत हो, तो द्वादशी तिथि समाप्त होने से पूर्व सूर्योदय के बाद केवल जल, गंगाजल अथवा चरणामृत ग्रहण करके एकादशी का 'प्रतीकात्मक पारणा' कर लेना चाहिए, और भोजन किए बिना प्रदोष व्रत निरंतर जारी रखना चाहिए।
        </div>
      </div>

    </div>
  
  `;
}
window.renderDrikPradosh = renderDrikPradosh;

// Helper to open Pradosh Katha page or modal
window.switchPradoshTab = function(tabKey, btn) {
  document.querySelectorAll('#page-pradosha-vrat-katha .pradosh-tab-content').forEach(el => el.style.display = 'none');
  const target = document.getElementById('pradosh-tab-' + tabKey);
  if(target) target.style.display = 'block';

  document.querySelectorAll('#page-pradosha-vrat-katha .katha-tab-btn').forEach(b => {
    b.style.background = '#FFF';
    b.style.color = '#78350F';
    b.style.border = '1px solid #D97706';
    b.classList.remove('active');
  });
  if(btn) {
    btn.style.background = '#78350F';
    btn.style.color = '#FFF';
    btn.style.border = 'none';
    btn.classList.add('active');
  }
};

window.openPradoshKathaModal = function(pradoshType) {
  if (typeof showPage === 'function') {
    showPage('page-pradosha-vrat-katha');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
};


