function renderDrikVinayaka(containerId) {
  const c = document.getElementById(containerId);
  if (!c) return;

  const rowsHtml = VINAYAKA_DATES_2026.map(item => {
    const highlightClass = item.isHighlight ? 'dp-row-highlight' : '';
    const moonSvg = getDrikMoonSvg(item.moon);
    const namesHtml = item.names.map(n => 
      `<a class="dp-subname-link" href="javascript:void(0);" onclick="openGaneshaKathaModal('${n.katha}')" title="${n.text} कथा एवं महत्व देखें">${n.text}</a>`
    ).join(', ');

    return `
      <div class="dp-row-item ${highlightClass}">
        <div class="dp-col-img-wrap" onclick="openGaneshaKathaModal('${item.names[0].katha}')" style="cursor:pointer;" title="${item.names.map(x => x.text).join(', ')} कथा एवं महत्व देखें">
          <img class="dp-deity-img" src="${item.img}" alt="${item.names[0].text}" onerror="this.src='assets/vinayaka_chaturthi_standard.jpg'">
        </div>
        <div class="dp-col-date-block">
          <div class="dp-col-date">${item.date}</div>
          <div class="dp-subnames-list">
            ${namesHtml}
            <div class="dp-muhurat-time" style="color:#111827; font-weight:600; font-size:0.88rem; margin-top:2px;">
              ${item.muhurat.replace('to', '<span style="color:#6B7280; font-weight:400;">to</span>')}
            </div>
          </div>
        </div>
        <div class="dp-col-moon-block">
          ${moonSvg}
          <div class="dp-paksha-label" style="font-size:0.8rem; color:#4B5563; font-weight:600; margin-top:3px; white-space:nowrap;">${item.duration}</div>
        </div>
        <div class="dp-col-tithi-block">
          <div class="dp-col-tithi-title">${item.tithi}</div>
          <div class="dp-col-timing-line">${item.begins}</div>
          <div class="dp-col-timing-line">${item.ends}</div>
        </div>
      </div>
    `;
  }).join('');

  c.innerHTML = `
    <div class="dp-calendar-card">
      <div class="dp-header-bar">
        <div class="dp-header-left">
          <div class="dp-header-title">2026 Ganesha Chaturthi Vrat Dates</div>
          <div class="dp-header-samvat">[2082 - 2083] Vikrama Samvata</div>
        </div>
        <button class="dp-katha-btn" onclick="openGaneshaKathaModal('सम्पूर्ण गणेश चतुर्थी व्रत')">
          <span class="dp-katha-icon">📖</span> Vrat Katha Ganesha Chaturthi
        </button>
      </div>
      <div class="dp-rows-container">
        ${rowsHtml}
      </div>
      <div class="dp-calendar-footer">
        <strong>Notes:</strong> All timings are represented in 12-hour notation in local time of <strong>New Delhi, India</strong> with DST adjustment (if applicable).<br>Hours which are past midnight are suffixed with next day date. In Panchang day starts and ends with sunrise.
      </div>
    </div>

    <!-- 🐘 2026 GANESHA CHATURTHI EDUCATIONAL & SPIRITUAL GUIDE CARD (Sanatan Panchang) 🐘 -->
    <div class="dp-calendar-card dp-ganesha-guide-card" style="margin-top:20px; padding:22px; background:#FFFDF9; border:1px solid #FDE68A; border-radius:12px; box-shadow:0 4px 14px rgba(0,0,0,0.05);">
      
      <!-- 1. 2026 Ganesha Chaturthi -->
      <div style="border-bottom:2px solid #FDE68A; padding-bottom:14px; margin-bottom:18px;">
        <h3 style="color:#7C2D12; font-size:1.35rem; font-weight:700; margin:0 0 6px 0; display:flex; align-items:center; gap:8px;">
          <span>🐘</span> 2026 Ganesha Chaturthi (विनायक चतुर्थी व्रत परिचय)
        </h3>
        <div style="color:#B45309; font-size:0.95rem; font-weight:600; margin-bottom:12px;">
          मासिक विनायक चतुर्थी एवं भाद्रपद गणेश जन्मोत्सव
        </div>

        <div style="display:flex; flex-wrap:wrap; gap:16px; align-items:flex-start; margin-bottom:12px;">
          <div style="flex:0 0 140px; max-width:160px;">
            <img src="assets/vinayaka_chaturthi_hero.jpg" alt="Lord Vinayaka" style="width:100%; border-radius:10px; border:2px solid #D97706; box-shadow:0 3px 8px rgba(0,0,0,0.12);" onerror="this.src='assets/vinayaka_puja_bhadrapada.jpg'">
          </div>
          <div style="flex:1; min-width:240px;">
            <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
              Each lunar month in Hindu calendar has two Chaturthi Tithis. According to Hindu scriptures Chaturthi Tithi(s) belongs to <strong>Lord Ganesha</strong>. The Chaturthi after Amavasya or new moon during Shukla Paksha is known as <strong>Vinayaka Chaturthi</strong> and the one after Purnimasi or full moon during Krishna Paksha is known as <a href="javascript:void(0);" onclick="openVratPage('sankashti')" style="color:#B45309; font-weight:600; text-decoration:underline;">Sankashti Chaturthi</a>.
            </p>
            <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
              Although Vinayaka Chaturthi fasting is done every month but the most significant Vinayaka Chaturthi falls in month of Bhadrapada. Vinayaka Chaturthi during Bhadrapada month is known as <a href="javascript:void(0);" onclick="showPage('page-ganeshchaturthi')" style="color:#B45309; font-weight:600; text-decoration:underline;" title="गणेश चतुर्थी 2026 पर्व विवरण देखें">Ganesha Chaturthi</a>. Ganesha Chaturthi is celebrated by Hindus all over the world as the birthday of Lord Ganesha.
            </p>
          </div>
        </div>

        <div style="background:rgba(254, 243, 199, 0.4); padding:10px 14px; border-radius:8px; font-size:0.9rem; color:#78350F; line-height:1.6; border:1px dashed #F59E0B;">
          <strong>हिन्दी भावार्थ:</strong> हिन्दू पंचांग के अनुसार प्रत्येक चन्द्र मास में दो चतुर्थी तिथियाँ आती हैं, जो भगवान श्री गणेश को समर्पित हैं। अमावस्या के बाद शुक्ल पक्ष की चतुर्थी को <strong>विनायक चतुर्थी</strong> तथा पूर्णिमा के बाद कृष्ण पक्ष की चतुर्थी को <strong>संकष्टी चतुर्थी</strong> कहा जाता है। यद्यपि विनायक चतुर्थी व्रत प्रत्येक माह रखा जाता है, परन्तु भाद्रपद मास के शुक्ल पक्ष की चतुर्थी का सबसे अधिक महत्व है, जिसे जगत्प्रसिद्ध <strong>गणेश चतुर्थी (गणेश जन्मोत्सव)</strong> के रूप में मनाया जाता है।
        </div>
      </div>

      <!-- 2. Varada Vinayaka Chaturthi -->
      <div style="background:#FEF3C7; border-left:4px solid #D97706; padding:16px; border-radius:0 10px 10px 0; margin-bottom:18px;">
        <h4 style="color:#92400E; font-size:1.18rem; font-weight:700; margin:0 0 10px 0; display:flex; align-items:center; gap:8px;">
          <span>🌺</span> Varad Vinayaka Chaturthi & Madhyahna Puja (वरद विनायक चतुर्थी एवं मध्याह्न पूजन)
        </h4>
        <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
          Vinayaka Chaturthi is also known as <strong>Varad Vinayaka Chaturthi</strong>. <strong>Varad</strong> means "asking God to fulfill any desire one has". Lord Ganesha blesses devotees with wisdom and patience who observe this fast. The wisdom and patience are two virtues whose significance is known to human kind since ages. Anyone who possesses these virtues can progress in life and can achieve whatever one desires.
        </p>
        <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
          Ganesha Puja on Vinayaka Chaturthi is done during afternoon which is <strong>midday (Madhyahna Kaal)</strong> according to Hindu calendar. The Muhurta to worship Lord Ganesha during afternoon is listed along with Vinayaka Chaturthi dates.
        </p>
        <div style="background:#FFFFFF; padding:10px 12px; border-radius:6px; font-size:0.88rem; color:#78350F; line-height:1.55;">
          <strong>मध्याह्न पूजन का महत्व:</strong> संकष्टी चतुर्थी में चन्द्रोदय के समय पूजन किया जाता है, जबकि विनायक चतुर्थी में भगवान गणेश का पूजन दोपहर (मध्याह्न काल) में किया जाता है। वरद का अर्थ है अभीष्ट वर देने वाला; इस व्रत के प्रभाव से बुद्धि, विवेक और धैर्य की प्राप्ति होती है।
        </div>
      </div>

      <!-- 3. Location based Ganesha Chaturthi Days -->
      <div style="background:#EFF6FF; border-left:4px solid #3B82F6; padding:16px; border-radius:0 10px 10px 0;">
        <h4 style="color:#1E40AF; font-size:1.18rem; font-weight:700; margin:0 0 10px 0; display:flex; align-items:center; gap:8px;">
          <span>📍</span> Location based Ganesha Chaturthi Days (स्थान भेद से विनायक चतुर्थी व्रत)
        </h4>
        <p style="color:#374151; font-size:0.95rem; line-height:1.65; margin:0 0 10px 0;">
          It is important to understand that fasting day for Vinayaka Chaturthi might differ for two cities even if those cities are within same Indian state. Fasting for Vinayaka Chaturthi depends on sunrise and sunset timings and it is observed when Chaturthi Tithi prevails during midday. Hence Vinayaka Chaturthi fasting might be observed on Tritiya Tithi i.e. one day before Chaturthi Tithi. As midday time depends on sunrise and sunset, which are different for all cities, it is important to refer Hindu calendar like this website which lists location based Vinayaka Chaturthi days. As generating location based dates are time consuming most sources ignore this fact and publish single list for all Indian cities.
        </p>
        <div style="background:#FFFFFF; padding:10px 12px; border-radius:6px; font-size:0.88rem; color:#1E3A8A; line-height:1.55;">
          <strong>स्थान भेद का कारण:</strong> विनायक चतुर्थी का व्रत मध्याह्न व्यापिनी चतुर्थी पर निर्भर करता है। प्रत्येक नगर में सूर्योदय और सूर्यास्त का समय अलग होने से मध्याह्न काल भिन्न होता है, इसलिए दो नगरों में व्रत का दिन अलग हो सकता है। यह पंचांग स्थान भेद के आधार पर पूर्णतया शुद्ध समय प्रदान करता है।
        </div>
      </div>

    </div>
  `;
}
window.renderDrikVinayaka = renderDrikVinayaka;

window.switchGaneshaTab = function(tabKey, btn) {
  document.querySelectorAll('#page-ganesha-chaturthi-katha .ganesha-tab-content').forEach(el => el.style.display = 'none');
  const target = document.getElementById('ganesha-tab-' + tabKey);
  if(target) target.style.display = 'block';

  document.querySelectorAll('#page-ganesha-chaturthi-katha .katha-tab-btn').forEach(b => {
    b.style.background = '#FFF';
    b.style.color = '#7A1706';
    b.style.border = '1px solid #D4A86A';
    b.classList.remove('active');
  });
  if(btn) {
    btn.style.background = '#7A1706';
    btn.style.color = '#FFF';
    btn.style.border = 'none';
    btn.classList.add('active');
  }
};

window.openGaneshaKathaModal = function(name) {
  if (typeof showPage === 'function') {
    showPage('page-ganesha-chaturthi-katha');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
};

