window.switchDwadashiTab = function(tabKey, btn) {
  document.querySelectorAll('#page-dwadashi-vrat-katha .dwadashi-tab-content').forEach(el => el.style.display = 'none');
  const target = document.getElementById('dwadashi-tab-' + tabKey);
  if(target) target.style.display = 'block';

  document.querySelectorAll('#page-dwadashi-vrat-katha .katha-tab-btn').forEach(b => {
    b.style.background = '#FFF';
    b.style.color = '#7A1706';
    b.style.border = '1px solid #D4A86A';
    b.classList.remove('active');
  });
  if(btn) {
    btn.style.background = '#7A1706';
    btn.style.color = '#FFF';
    btn.style.border = 'none';
    btn.classList.add('active');
  }
};

window.openDwadashiKathaModal = function(name) {
  if (typeof showPage === 'function') {
    showPage('page-dwadashi-vrat-katha');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }
};

window.renderDrikDwadashi = renderDrikDwadashi;
