function openMahadwadashiDetailModal(id) {
  const item = MAHADWADASHI_COLLECTION_DATA[id];
  if (!item) return;

  let modalBackdrop = document.getElementById('mahadwadashi-modal-backdrop');
  if (!modalBackdrop) {
    modalBackdrop = document.createElement('div');
    modalBackdrop.id = 'mahadwadashi-modal-backdrop';
    modalBackdrop.style.cssText = 'display:none; position:fixed; top:0; left:0; width:100%; height:100%; background:rgba(0,0,0,0.65); z-index:99999; justify-content:center; align-items:center; padding:16px; box-sizing:border-box; backdrop-filter:blur(4px);';
    modalBackdrop.onclick = function(e) {
      if (e.target === modalBackdrop) closeMahadwadashiModal();
    };
    document.body.appendChild(modalBackdrop);
  }

  // Diagram HTML if exists
  let diagramHtml = '';
  if (item.diagram && item.diagram.length > 0) {
    const boxes = item.diagram.map(d => {
      const bg = d.highlight ? 'background:linear-gradient(135deg, #7C2D12, #B91C1C); color:#FFF; border:2px solid #F59E0B; box-shadow:0 3px 10px rgba(185,28,28,0.3); font-weight:800;' : 'background:#FEF3C7; color:#78350F; border:1px solid #FCD34D; font-weight:700;';
      return `<div style="padding:8px 12px; border-radius:8px; text-align:center; min-width:80px; ${bg}">
        <div style="font-size:1.1rem; line-height:1.2;">${d.tithi}</div>
        <div style="font-size:0.75rem; margin-top:2px; opacity:0.95;">${d.label}</div>
      </div>`;
    }).join('<span style="color:#B45309; font-weight:900; font-size:1.2rem; align-self:center;">➔</span>');

    diagramHtml = `
      <div style="background:#FFFDF8; border:1px solid #F3CCA1; border-radius:10px; padding:14px; margin-bottom:16px;">
        <div style="font-size:0.85rem; font-weight:800; color:#92400E; margin-bottom:10px; display:flex; align-items:center; gap:6px;">
          <span>📊 तिथि संयोग आरेख (Tithi Alignment Diagram):</span>
        </div>
        <div style="display:flex; flex-wrap:wrap; gap:8px; align-items:center; justify-content:center;">
          ${boxes}
        </div>
      </div>
    `;
  }

  const parasHtml = item.paragraphs.map(p => {
    // Check if it looks like a diagram line (| 10 | 11 | ...)
    if (p.trim().startsWith('|') && p.trim().endsWith('|')) {
      return ''; // Already handled in diagramHtml
    }
    return `<p style="font-size:0.96rem; line-height:1.75; color:#374151; margin:0 0 14px 0; text-align:justify;">${p}</p>`;
  }).join('');

  modalBackdrop.innerHTML = `
    <div style="background:#FFFDF9; border:2px solid #D6A057; border-radius:14px; max-width:720px; width:100%; max-height:88vh; display:flex; flex-direction:column; box-shadow:0 14px 40px rgba(0,0,0,0.35); animation:dpModalFadeIn 0.25s ease-out; overflow:hidden;">
      
      <!-- Header -->
      <div style="background:linear-gradient(135deg, #7C2D12 0%, #991B1B 100%); color:#FFFDF8; padding:16px 20px; display:flex; justify-content:space-between; align-items:center;">
        <div style="display:flex; align-items:center; gap:12px;">
          <img src="assets/lord_vishnu_garuda.png" alt="${item.name}" style="width:44px; height:44px; object-fit:contain; filter:drop-shadow(0 2px 4px rgba(0,0,0,0.25));" onerror="this.src='assets/dwadashi_vishnu_garuda.jpg'">
          <div>
            <h3 style="margin:0; font-size:1.3rem; font-weight:800; color:#FFFFFF; letter-spacing:0.3px;">${item.name}</h3>
            <div style="font-size:0.86rem; color:#FEF3C7; font-weight:600;">${item.hindi_name}</div>
          </div>
        </div>
        <button onclick="closeMahadwadashiModal()" style="background:rgba(255,255,255,0.2); border:none; color:#FFF; font-size:1.25rem; width:34px; height:34px; border-radius:50%; cursor:pointer; display:flex; align-items:center; justify-content:center; line-height:1; transition:background 0.2s;">✕</button>
      </div>

      <!-- Quick Info Bar -->
      <div style="background:#FEF3C7; border-bottom:1px solid #FCD34D; padding:10px 18px; display:flex; flex-wrap:wrap; gap:14px; justify-content:space-between; font-size:0.85rem; color:#78350F; font-weight:700;">
        <div>📜 धर्मग्रंथ: <span style="color:#9A3412;">${item.scriptures}</span></div>
        <div>🕉️ इष्टदेव: <span style="color:#9A3412;">भगवान श्री हरि विष्णु</span></div>
      </div>

      <!-- Body -->
      <div style="padding:20px 22px 14px 22px; overflow-y:auto; flex:1;">
        
        <!-- Short Definition Box -->
        ${item.short_def ? `
        <div style="background:#FFF7ED; border-left:4px solid #EA580C; padding:12px 14px; border-radius:0 8px 8px 0; margin-bottom:18px; font-size:0.95rem; color:#9A3412; font-weight:600; line-height:1.6;">
          ✨ ${item.short_def}
        </div>` : ''}

        <!-- Diagram -->
        ${diagramHtml}

        <!-- Full Text Paragraphs -->
        <div style="margin-top:6px;">
          ${parasHtml}
        </div>
      </div>

      <!-- Footer Buttons -->
      <div style="background:#FDF3E7; border-top:1px solid #E8C8A0; padding:12px 20px; display:flex; justify-content:space-between; align-items:center; flex-wrap:wrap; gap:10px;">
        <div style="display:flex; gap:8px;">
          <button onclick="closeMahadwadashiModal(); openVratPage('dwadashi');" style="background:#FFF; color:#92400E; border:1px solid #D97706; padding:7px 14px; border-radius:6px; font-weight:700; font-size:0.86rem; cursor:pointer;">
            🗓️ 2026 Dwadashi Dates
          </button>
          <button onclick="closeMahadwadashiModal(); openDwadashiKathaModal('सम्पूर्ण द्वादशी व्रत');" style="background:#7C2D12; color:#FFF; border:none; padding:7px 14px; border-radius:6px; font-weight:700; font-size:0.86rem; cursor:pointer;">
            📖 द्वादशी व्रत कथा
          </button>
        </div>
        <button onclick="closeMahadwadashiModal()" style="background:#D97706; color:#FFF; border:none; padding:7px 18px; border-radius:6px; font-weight:700; font-size:0.88rem; cursor:pointer;">
          बंद करें
        </button>
      </div>

    </div>
  `;

  modalBackdrop.style.display = 'flex';
}

function closeMahadwadashiModal() {
  const modalBackdrop = document.getElementById('mahadwadashi-modal-backdrop');
  if (modalBackdrop) modalBackdrop.style.display = 'none';
}

