function openVratPage(vratKey) {
  const data = VRAT_PAGES_DATA[vratKey];
  if(!data) return;
  
  const titleEl = document.getElementById('vrat-page-title');
  if(titleEl) titleEl.textContent = data.title;
  
  const imgEl = document.getElementById('vrat-hero-img');
  if(imgEl) imgEl.src = data.heroImg;
  
  const hTitleEl = document.getElementById('vrat-hero-title');
  if(hTitleEl) hTitleEl.textContent = data.heroTitle;
  
  const hSubEl = document.getElementById('vrat-hero-subtitle');
  if(hSubEl) hSubEl.textContent = data.heroSubtitle;
  
  const relTitleEl = document.getElementById('vrat-related-title');
  if(relTitleEl) relTitleEl.textContent = data.relatedTitle;

  const datesWrap = document.getElementById('vrat-dates-container');
  if(datesWrap) {
    if(vratKey === 'ekadashi') {
      renderDrikEkadashi('vrat-dates-container');
    } else if(vratKey === 'pradosham' || vratKey === 'pradosh') {
      renderDrikPradosh('vrat-dates-container');
    } else if(vratKey === 'sankashti' || vratKey === 'page-sankashti') {
      renderDrikSankashti('vrat-dates-container');
    } else if(vratKey === 'vinayaka-chaturthi' || vratKey === 'ganesha-chaturthi' || vratKey === 'vinayaka') {
      renderDrikVinayaka('vrat-dates-container');
    } else if(vratKey === 'dwadashi') {
      renderDrikDwadashi('vrat-dates-container');
    } else if(vratKey === 'mahadwadashi') {
      renderDrikMahadwadashi('vrat-dates-container');
    } else if(vratKey === 'masik-shivaratri' || vratKey === 'shivaratri' || vratKey === 'maha-shivaratri') {
      renderDrikShivaratri('vrat-dates-container');
    } else if(data.dates && data.dates.length > 0) {
      datesWrap.innerHTML = data.dates.map(d => 
        `<div class="sk-date-card" style="display:flex; align-items:center; gap:0.8rem;">
           <img src="${d.img || data.heroImg}" style="width:65px; height:65px; border-radius:12px; object-fit:cover; border:2px solid var(--saffron);">
           <div class="sk-date-left" style="min-width:60px;">
             <div class="sk-month">${d.month}</div>
             <div class="sk-day" style="font-size:1.8rem;">${d.day}</div>
             <div class="sk-weekday">${d.weekday}</div>
           </div>
           <div class="sk-date-right" style="flex:1;">
             <div class="sk-name" style="font-size:1.05rem; font-weight:800; color:var(--maroon); margin-bottom:0.2rem;">${d.name}</div>
             <div class="sk-tithi" style="font-size:0.85rem; color:#475569;">${d.tithi || ''}</div>
           </div>
         </div>`
      ).join('');
    } else {
      datesWrap.innerHTML = '<div style="padding: 2rem; text-align: center; color: var(--text-mid);">तिथियाँ लोड हो रही हैं...</div>';
    }
  }

  const relWrap = document.getElementById('vrat-related-grid');
  if(relWrap) {
    relWrap.innerHTML = data.related.map(r => 
      `<div class="sk-rel-card">
         <div class="sk-rel-icon">${r.emoji}</div>
         <div class="sk-rel-name">${r.name}</div>
       </div>`
    ).join('');
  }

  showPage('page-vrat-detail');
}
window.openVratPage = openVratPage;

