function getGiftIndex() {
  let savedIdx = parseInt(localStorage.getItem('bhakti_gift_idx') || '0');
  return savedIdx % DIVINE_REWARD_GIFTS.length;
}

function claimDivineGift() {
  const modal = document.getElementById('divine-gift-modal');
  const tEl = document.getElementById('gift-modal-title');
  const mEl = document.getElementById('gift-modal-mantra');
  const meanEl = document.getElementById('gift-modal-meaning');
  const subEl = document.getElementById('gift-progress-subtitle');

  const idx = getGiftIndex();
  const gift = DIVINE_REWARD_GIFTS[idx];

  if (tEl) tEl.textContent = gift.title;
  if (mEl) mEl.textContent = gift.mantra;
  if (meanEl) meanEl.innerHTML = `<span style="background:#EC4899; color:#FFF; font-size:0.75rem; font-weight:800; padding:2px 8px; border-radius:10px; margin-bottom:4px; display:inline-block;">${gift.badge}</span><br>📖 <strong>फलश्रुति:</strong> ${gift.meaning}`;

  if (modal) {
    modal.classList.remove('hidden');
    modal.style.display = 'flex';
    triggerFlowerShower();
  }
}

function closeDivineGiftModal() {
  const modal = document.getElementById('divine-gift-modal');
  if (modal) {
    modal.classList.add('hidden');
    setTimeout(() => { modal.style.display = 'none'; }, 300);
  }
}

function reciteGiftMantra() {
  const idx = getGiftIndex();
  const gift = DIVINE_REWARD_GIFTS[idx];
  
  // Advance to next unique gift for next time
  const nextIdx = (idx + 1) % DIVINE_REWARD_GIFTS.length;
  localStorage.setItem('bhakti_gift_idx', nextIdx.toString());

  const subEl = document.getElementById('gift-progress-subtitle');
  if (subEl) {
    subEl.textContent = `अगला उपहार #${nextIdx + 1}: अनलॉक्ड ❯`;
  }

  closeDivineGiftModal();
  openReader({ title: gift.title, text: gift.mantra + '\n\n' + gift.meaning, deity: gift.badge }, 'page-home');
  showToast(`🌸 ${gift.badge} ग्रहण किया गया! अगला नया उपहार तैयार!`);
}

window.claimDivineGift = claimDivineGift;
window.closeDivineGiftModal = closeDivineGiftModal;
window.reciteGiftMantra = reciteGiftMantra;


