// ══════════════════════════════════════════════════════
// ══════════════════════════════════════════════════════
// 🖼️ TRUE INFINITE CIRCULAR RING 3D COVERFLOW (3s PAUSE LOOP)
// ══════════════════════════════════════════════════════

let currentCoverflowIdx = 3; // Center: Shri Krishna
let coverflowTimer = null;

const COVERFLOW_SUBTITLES = [
  '॥ श्री हनुमान जी महाराज की जय ॥',
  '॥ जय माँ जगदम्बे भवानी ॥',
  '॥ ॐ नमः शिवाय ॥',
  '॥ हरे कृष्णा हरे रामा ॥',
  '॥ ॐ नमो भगवते वासुदेवाय ॥',
  '॥ ॐ श्रीं महालक्ष्म्यै नमः ॥',
  '॥ ॐ गं गणपतये नमः ॥',
  '॥ ॐ ऐं सरस्वत्यै नमः ॥'
];

function updateCoverflow3D() {
  const cards = document.querySelectorAll('.coverflow-card');
  const subTitle = document.getElementById('god-coverflow-sub');
  if (!cards.length) return;

  const total = cards.length;
  currentCoverflowIdx = ((currentCoverflowIdx % total) + total) % total;

  cards.forEach((card, idx) => {
    // True Circular Modulo Distance calculation
    let diff = idx - currentCoverflowIdx;
    while (diff > total / 2) diff -= total;
    while (diff <= -total / 2) diff += total;

    if (diff === 0) {
      // 🌟 CENTER ACTIVE CARD (LARGE & FRONT-FACING)
      card.style.transform = 'translateX(0px) translateZ(90px) scale(1.22) rotateY(0deg)';
      card.style.zIndex = '100';
      card.style.opacity = '1';
      card.style.filter = 'brightness(1.18)';
      card.classList.add('active-center');
    } else if (diff === -1) {
      // IMMEDIATE LEFT (Cards seamlessly wrap behind from right to left)
      card.style.transform = 'translateX(-100px) translateZ(0px) scale(0.85) rotateY(32deg)';
      card.style.zIndex = '80';
      card.style.opacity = '0.88';
      card.style.filter = 'brightness(0.8)';
      card.classList.remove('active-center');
    } else if (diff === 1) {
      // IMMEDIATE RIGHT (Cards seamlessly wrap around)
      card.style.transform = 'translateX(100px) translateZ(0px) scale(0.85) rotateY(-32deg)';
      card.style.zIndex = '80';
      card.style.opacity = '0.88';
      card.style.filter = 'brightness(0.8)';
      card.classList.remove('active-center');
    } else if (diff === -2) {
      // FAR LEFT
      card.style.transform = 'translateX(-175px) translateZ(-65px) scale(0.68) rotateY(48deg)';
      card.style.zIndex = '60';
      card.style.opacity = '0.55';
      card.style.filter = 'brightness(0.6)';
      card.classList.remove('active-center');
    } else if (diff === 2) {
      // FAR RIGHT
      card.style.transform = 'translateX(175px) translateZ(-65px) scale(0.68) rotateY(-48deg)';
      card.style.zIndex = '60';
      card.style.opacity = '0.55';
      card.style.filter = 'brightness(0.6)';
      card.classList.remove('active-center');
    } else {
      // HIDDEN OUTSIDE BOUNDS IN THE CIRCULAR QUEUE
      const transX = diff < 0 ? -250 : 250;
      card.style.transform = `translateX(${transX}px) translateZ(-130px) scale(0.48) rotateY(${diff < 0 ? 60 : -60}deg)`;
      card.style.zIndex = '10';
      card.style.opacity = '0';
      card.style.filter = 'brightness(0.2)';
      card.classList.remove('active-center');
    }
  });

  if (subTitle && COVERFLOW_SUBTITLES[currentCoverflowIdx]) {
    subTitle.textContent = COVERFLOW_SUBTITLES[currentCoverflowIdx];
  }
}

function nextCoverflowStep() {
  const cards = document.querySelectorAll('.coverflow-card');
  if (!cards.length) return;
  currentCoverflowIdx = (currentCoverflowIdx + 1) % cards.length;
  updateCoverflow3D();
}

function selectCoverflow(idx) {
  currentCoverflowIdx = idx;
  updateCoverflow3D();
  resetCoverflowTimer();
}

function resetCoverflowTimer() {
  if (coverflowTimer) clearInterval(coverflowTimer);
  coverflowTimer = setInterval(nextCoverflowStep, 3600); // 3 seconds stay at center + 0.6s slide
}

function initCoverflow3D() {
  setTimeout(() => {
    updateCoverflow3D();
    resetCoverflowTimer();
  }, 300);
}

window.initCoverflow3D = initCoverflow3D;
window.selectCoverflow = selectCoverflow;
window.nextCoverflowStep = nextCoverflowStep;


