function changeAppLanguage(langKey) {
  if (langKey && langKey !== 'hi') {
    console.log('[🌐 i18n] Language is locked to Hindi. Ignored:', langKey);
    localStorage.setItem('bhakti_app_language', 'hi');
    localStorage.setItem('user_app_language', 'hi');
    window.currentAppLanguage = 'hi';
    if (typeof showLanguageLockedNotice === 'function') showLanguageLockedNotice();
    langKey = 'hi';
  }
  const dict = FULL_APP_DICTIONARY['hi'] || FULL_APP_DICTIONARY[langKey] || {};
  localStorage.setItem('bhakti_app_language', langKey);

  // 1. Translate all data-i18n elements across the DOM
  document.querySelectorAll('[data-i18n]').forEach(el => {
    const key = el.dataset.i18n;
    if (dict[key]) {
      el.textContent = dict[key];
    }
  });

  // 2. Translate Bottom Navigation Bar labels
  const navItems = document.querySelectorAll('.bottom-nav .nav-item');
  if (navItems.length >= 5) {
    if (navItems[0].querySelector('.nav-label')) navItems[0].querySelector('.nav-label').textContent = dict.nav_panchang || 'Panchang';
    if (navItems[1].querySelector('.nav-label')) navItems[1].querySelector('.nav-label').textContent = dict.nav_jar || 'Kalash';
    if (navItems[2].querySelector('.nav-label')) navItems[2].querySelector('.nav-label').textContent = dict.nav_home || 'Home';
    if (navItems[3].querySelector('.nav-label')) navItems[3].querySelector('.nav-label').textContent = dict.nav_katha || 'Stories';
    if (navItems[4].querySelector('.nav-label')) navItems[4].querySelector('.nav-label').textContent = dict.nav_profile || 'Profile';
  }

  // 3. Translate Sticky App Header Title
  const hdrTitle = document.querySelector('.header-title');
  if (hdrTitle) hdrTitle.textContent = dict.app_title || 'Devotion in Bhakti';

  // 4. Translate Hero Section Title & Subtitles
  const heroTitle = document.getElementById('god-coverflow-title');
  if (heroTitle) heroTitle.textContent = dict.hero_title || 'Devotion in Bhakti';

  const heroSub = document.getElementById('god-focus-sub');
  if (heroSub) heroSub.textContent = dict.hero_sub || '॥ Holy Darshan and Worship of All Deities ॥';

  const heroShloka = document.querySelector('.bhakti-shloka-bar');
  if (heroShloka) heroShloka.textContent = dict.hero_shloka || '✨ May all beings be happy, may all be free from illness ✨';

  // 5. Translate Category Grid Cards
  document.querySelectorAll('.cat-card').forEach(card => {
    const pageId = card.dataset.page;
    const nameEl = card.querySelector('.cat-name');
    if (nameEl) {
      if (pageId === 'page-aarti') nameEl.textContent = dict.aarti || 'Aarti';
      if (pageId === 'page-chalisa') nameEl.textContent = dict.chalisa || 'Chalisa';
      if (pageId === 'page-mantra') nameEl.textContent = dict.mantra || 'Mantra';
      if (pageId === 'page-panchang') nameEl.textContent = dict.panchang || 'Panchang';
      if (pageId === 'page-vrats') nameEl.textContent = dict.vrat_tyohar || 'Vrats & Festivals';
      if (pageId === 'page-top10') nameEl.textContent = dict.top_festivals || 'Top 10 Festivals';
      if (pageId === 'page-profile') nameEl.textContent = dict.profile || 'Profile';
    }
  });

  // 6. Update Language Selector Value
  const langSelect = document.getElementById('app-language-select');
  if (langSelect) langSelect.value = langKey;

  showToast(dict.lang_changed || `🌐 Language changed to ${langKey.toUpperCase()}`);
}

window.changeAppLanguage = changeAppLanguage;

// ══════════════════════════════════════════════════════
// 🪔 DYNAMIC FESTIVAL READER ENGINE (data/festivals_detail.json)
// ══════════════════════════════════════════════════════

let ALL_FESTIVALS_DATA = [];

async function loadFestivalsDetailData() {
  try {
    const res = await fetch('data/festivals_detail.json');
    if (res.ok) {
      const data = await res.json();
      ALL_FESTIVALS_DATA = data.festivals || [];
      console.log('Loaded festivals_detail.json successfully!', ALL_FESTIVALS_DATA.length);
    }
  } catch(e) {
    console.error('Failed to load festivals_detail.json:', e);
  }
}

document.addEventListener('DOMContentLoaded', () => {
  loadFestivalsDetailData();
});

async function openFestivalDetailByName(festName) {
  if (festName && (festName.includes('सकट चौथ') || festName.toLowerCase().includes('sakat chauth'))) {
    showPage('page-sakat-chauth');
    return;
  }
  if (festName && (festName.includes('लम्बोदर') || festName.toLowerCase().includes('lambodara'))) {
    showPage('page-lambodara-sankashti');
    return;
  }

  if (!ALL_FESTIVALS_DATA || ALL_FESTIVALS_DATA.length === 0) {
    await loadFestivalsDetailData();
  }

  // Find matching festival in JSON
  const fest = ALL_FESTIVALS_DATA.find(f => 
    f.festivalName.trim() === festName.trim() || 
    (f.alternateNames && f.alternateNames.some(alt => alt.toLowerCase().includes(festName.toLowerCase())))
  );

  if (!fest) {
    console.warn('Festival not found in JSON:', festName);
    showToast('⚠️ इस त्यौहार का विवरण जल्द आ रहा है!');
    return;
  }

  // Render Festival Data
  CURRENT_FESTIVAL_OBJ = fest;
  selectFestYear('2026');
  document.getElementById('fest-header-title').textContent = fest.festivalName;
  document.getElementById('fest-hero-name').textContent = fest.festivalName;
  document.getElementById('fest-hero-date').textContent = `${fest.date} (${fest.weekday || ''})`;
  document.getElementById('fest-hero-alt').textContent = fest.alternateNames ? fest.alternateNames.join(' • ') : '';
  document.getElementById('fest-hero-tithi').textContent = `🚩 ${fest.hinduCalendarDate || fest.tithi || ''}`;

  // Timings Grid
  const grid = document.getElementById('fest-timings-grid');
  grid.innerHTML = `
    <div style="background: rgba(254, 243, 199, 0.5); padding: 0.6rem; border-radius: 12px;">
      <div style="font-size: 0.75rem; color: #92400E; font-weight: 700;">🌅 सूर्योदय</div>
      <div style="font-weight: 800; color: #78350F;">${fest.sunrise || '06:30 AM'}</div>
    </div>
    <div style="background: rgba(254, 243, 199, 0.5); padding: 0.6rem; border-radius: 12px;">
      <div style="font-size: 0.75rem; color: #92400E; font-weight: 700;">🌇 सूर्यास्त</div>
      <div style="font-weight: 800; color: #78350F;">${fest.sunset || '05:45 PM'}</div>
    </div>
    <div style="background: rgba(254, 243, 199, 0.5); padding: 0.6rem; border-radius: 12px; grid-column: span 2;">
      <div style="font-size: 0.75rem; color: #92400E; font-weight: 700;">⏰ पूजा शुभ मुहूर्त</div>
      <div style="font-weight: 800; color: #78350F;">${fest.pujaMuhurat || fest.deepdanTime || 'प्रदोष काल / शुभ मुहूर्त'}</div>
    </div>
  `;

  // Overview Tab
  document.getElementById('fest-sig-text').textContent = fest.significance || '';
  document.getElementById('fest-about-text').textContent = fest.aboutFestival || '';
  
  const deitiesList = document.getElementById('fest-deities-list');
  deitiesList.innerHTML = (fest.deity || fest.deities || ['भगवान श्री कृष्ण']).map(d => 
    `<span style="background:#FEF3C7; color:#B45309; border:1px solid #FDE68A; padding:6px 14px; border-radius:20px; font-weight:700; font-size:0.85rem;">🚩 ${d}</span>`
  ).join('');

  // Special Chhath 4-Days Tab
  const chhathTabBtn = document.getElementById('tab-chhath-4days');
  const chhathContainer = document.getElementById('chhath-4days-container');
  if (fest.fourDays) {
    chhathTabBtn.style.display = 'inline-block';
    let cHtml = '';
    const days = [fest.fourDays.nahayKhay, fest.fourDays.kharna, fest.fourDays.sandhyaArghya, fest.fourDays.ushaArghya];
    days.forEach(d => {
      if (!d) return;
      cHtml += `
        <div class="reader-card" style="margin-bottom: 1rem; border-top: 4px solid var(--saffron);">
          <h3 style="color: var(--saffron); font-size: 1.1rem; font-weight: 900; margin-bottom: 0.4rem;">${d.dayName}</h3>
          <div style="font-size: 0.85rem; color: #64748B; margin-bottom: 0.8rem;">📅 तिथि: ${d.date} (${d.tithi}) | ⏰ ${d.timing}</div>
          <p style="font-size: 0.93rem; line-height: 1.6; margin-bottom: 0.6rem;"><strong>पावन विधि:</strong> ${d.ritual}</p>
          <p style="font-size: 0.93rem; line-height: 1.6; margin-bottom: 0.6rem;"><strong>विस्तृत विवरण:</strong> ${d.pujaDetails}</p>
          <div style="background:#FFFBEB; padding:0.6rem 0.9rem; border-radius:12px; font-size:0.88rem; color:#92400E;"><strong>🍧 विशेष प्रसाद:</strong> ${d.prasad}</div>
        </div>
      `;
    });
    chhathContainer.innerHTML = cHtml;
  } else {
    chhathTabBtn.style.display = 'none';
  }

  // Vidhi Tab
  const vidhiList = document.getElementById('fest-vidhi-list');
  vidhiList.innerHTML = (fest.pujaVidhi || []).map(v => `<li style="margin-bottom:0.5rem;">${v}</li>`).join('');

  const samagriGrid = document.getElementById('fest-samagri-grid');
  samagriGrid.innerHTML = (fest.pujaSamagri || []).map(s => 
    `<div style="background:#F8FAFC; border:1px solid #E2E8F0; padding:0.6rem 0.8rem; border-radius:12px; font-size:0.88rem; color:#334155; font-weight:600;">🌿 ${s}</div>`
  ).join('');

  const prasadList = document.getElementById('fest-prasad-list');
  prasadList.innerHTML = (fest.prasad || []).map(p => 
    `<span style="background:#ECFDF5; color:#047857; border:1px solid #A7F3D0; padding:6px 14px; border-radius:20px; font-weight:700; font-size:0.85rem;">🍯 ${p}</span>`
  ).join('');

  // Mantras Tab
  const mantrasList = document.getElementById('fest-mantras-list');
  mantrasList.innerHTML = (fest.mantras || []).map(m => `
    <div style="background: linear-gradient(135deg, #FFFBEB 0%, #FEF3C7 100%); border: 1px solid #FDE68A; padding: 1rem; border-radius: 16px; margin-bottom: 0.8rem;">
      <div style="font-weight: 800; color: #B45309; font-size: 1rem; line-height: 1.6;">${m}</div>
    </div>
  `).join('');

  const songsList = document.getElementById('fest-songs-list');
  songsList.innerHTML = (fest.devotionalSongs || []).map(s => `
    <div style="display: flex; align-items: center; justify-content: space-between; background: #F1F5F9; padding: 0.7rem 1rem; border-radius: 12px; margin-bottom: 0.5rem;">
      <span style="font-weight: 700; color: #1E293B;">🎶 ${s}</span>
      <span style="color: var(--saffron); font-weight: 800; font-size: 0.85rem;">▶ प्ले</span>
    </div>
  `).join('');

  // Katha Tab
  document.getElementById('fest-mythology-text').textContent = fest.mythology || '';
  const storiesList = document.getElementById('fest-stories-list');
  storiesList.innerHTML = (fest.relatedStories || []).map(st => `
    <div style="background: #F8FAFC; border-left: 3px solid var(--saffron); padding: 0.7rem 1rem; margin-bottom: 0.6rem; border-radius: 0 12px 12px 0;">
      <span style="font-size: 0.92rem; color: #334155; font-weight: 600;">📖 ${st}</span>
    </div>
  `).join('');

  // Rules Tab (Dos & Don'ts)
  document.getElementById('fest-todo-list').innerHTML = (fest.whatToDo || []).map(item => `<li>${item}</li>`).join('');
  document.getElementById('fest-notdo-list').innerHTML = (fest.whatNotToDo || []).map(item => `<li>${item}</li>`).join('');
  
  const placesList = document.getElementById('fest-places-list');
  placesList.innerHTML = (fest.importantPlaces || []).map(p => 
    `<span style="background:#EFF6FF; color:#1D4ED8; border:1px solid #BFDBFE; padding:6px 14px; border-radius:20px; font-weight:700; font-size:0.85rem;">🏛️ ${p}</span>`
  ).join('');

  // Dates Tab
  const datesTable = document.getElementById('fest-dates-table');
  datesTable.innerHTML = `
    <tr style="background:#F1F5F9;"><th style="padding:8px; border:1px solid #CBD5E1;">वर्ष</th><th style="padding:8px; border:1px solid #CBD5E1;">दिनांक (Date)</th></tr>
    <tr><td style="padding:8px; border:1px solid #E2E8F0; font-weight:700;">२०२६ (Previous Year)</td><td style="padding:8px; border:1px solid #E2E8F0;">${fest.previousYearDate || '2026'}</td></tr>
    <tr style="background:#FEF3C7; font-weight:800;"><td style="padding:8px; border:1px solid #FDE68A; color:#B45309;">२०२७ (Current Year)</td><td style="padding:8px; border:1px solid #FDE68A; color:#B45309;">${fest.currentYearDate || fest.date}</td></tr>
    <tr><td style="padding:8px; border:1px solid #E2E8F0; font-weight:700;">२०२८ (Next Year)</td><td style="padding:8px; border:1px solid #E2E8F0;">${fest.nextYearDate || '2028'}</td></tr>
  `;

  document.getElementById('fest-facts-list').innerHTML = (fest.interestingFacts || []).map(f => `<li>${f}</li>`).join('');

  // Switch to default Overview Tab
  switchFestTab('overview');

  // Open Page
  showPage('page-festival-reader');
}

function switchFestTab(tabName) {
  document.querySelectorAll('.fest-tab-pane').forEach(p => p.style.display = 'none');
  document.querySelectorAll('#fest-tabs-bar .vrat-tab').forEach(b => b.classList.remove('active'));

  const targetPane = document.getElementById(`fest-tab-${tabName}`);
  if (targetPane) targetPane.style.display = 'block';

  // Activate clicked tab button
  const btns = document.querySelectorAll('#fest-tabs-bar .vrat-tab');
  btns.forEach(b => {
    if (b.getAttribute('onclick') && b.getAttribute('onclick').includes(tabName)) {
      b.classList.add('active');
    }
  });
}

function shareCurrentFestival() {
  const name = document.getElementById('fest-header-title').textContent || 'त्यौहार';
  if (navigator.share) {
    navigator.share({
      title: name,
      text: `${name} २०२७ का पावन मुहूर्त, पूजा विधि एवं सम्पूर्ण कथा भक्ति ऐप पर देखें!`,
      url: window.location.href
    });
  } else {
    showToast('📤 त्यौहार लिंक कॉपी हो गया!');
  }
}

window.openFestivalDetailByName = openFestivalDetailByName;
window.switchFestTab = switchFestTab;
window.shareCurrentFestival = shareCurrentFestival;

