function formatAudioDuration(sec) {
  if (isNaN(sec) || sec <= 0) return '00:00';
  const h = Math.floor(sec / 3600);
  const m = Math.floor((sec % 3600) / 60);
  const s = Math.floor(sec % 60);
  if (h > 0) {
    return `${h < 10 ? '0' : ''}${h}:${m < 10 ? '0' : ''}${m}:${s < 10 ? '0' : ''}${s}`;
  }
  return `${m < 10 ? '0' : ''}${m}:${s < 10 ? '0' : ''}${s}`;
}

var DEVOTIONAL_KATHAS = FULL_KATHA_PLAYLIST.map(p => ({
  id: p.kathaId,
  title: p.title,
  subtitle: p.sub,
  category: p.category,
  img: p.img,
  duration: formatAudioDuration(p.durationSecs),
  speaker: p.sub.split('•')[0].trim(),
  desc: p.desc,
  audio: p.src
}));

var currentKathaTrackIndex = 0;
var isAudioShuffleMode = false;
var isAudioRepeatMode = false;
var audioTimelineTicker = null;

if (typeof window.coreAudioElement === 'undefined' || !window.coreAudioElement) {
  window.coreAudioElement = new Audio();
  window.audioPlayerObj = window.coreAudioElement;

  function handleAudioTimelineUpdate() {
    const audio = window.coreAudioElement;
    const track = FULL_KATHA_PLAYLIST[currentKathaTrackIndex] || FULL_KATHA_PLAYLIST[0];
    
    let cur = audio.currentTime || 0;
    let dur = (!isNaN(audio.duration) && audio.duration > 0) ? audio.duration : (track.durationSecs || 300);
    
    const pct = dur > 0 ? Math.min(100, (cur / dur) * 100) : 0;
    const curStr = formatAudioDuration(cur);
    const durStr = formatAudioDuration(dur);

    // Update Mini Player
    const miniTime = document.getElementById('glass-mini-time');
    if (miniTime) miniTime.textContent = `${curStr} / ${durStr}`;

    // Update Full Modal Seekbar & Time Displays
    const mCur = document.getElementById('glass-modal-cur-time');
    if (mCur) mCur.textContent = curStr;

    const mTot = document.getElementById('glass-modal-tot-time');
    if (mTot) mTot.textContent = durStr;

    const seek = document.getElementById('glass-modal-seekbar');
    if (seek && document.activeElement !== seek) {
      seek.value = pct;
    }
  }

  window.coreAudioElement.addEventListener('timeupdate', handleAudioTimelineUpdate);
  window.coreAudioElement.addEventListener('loadedmetadata', handleAudioTimelineUpdate);
  window.coreAudioElement.addEventListener('durationchange', handleAudioTimelineUpdate);
  window.coreAudioElement.addEventListener('canplay', handleAudioTimelineUpdate);

  window.coreAudioElement.addEventListener('play', () => {
    window.isAudioPlaying = true;
    updateAllPlayButtons(true);
    if (audioTimelineTicker) clearInterval(audioTimelineTicker);
    audioTimelineTicker = setInterval(handleAudioTimelineUpdate, 500);
  });

  window.coreAudioElement.addEventListener('pause', () => {
    window.isAudioPlaying = false;
    updateAllPlayButtons(false);
    if (audioTimelineTicker) {
      clearInterval(audioTimelineTicker);
      audioTimelineTicker = null;
    }
    handleAudioTimelineUpdate();
  });

  window.coreAudioElement.addEventListener('ended', () => {
    if (isAudioRepeatMode) {
      window.coreAudioElement.currentTime = 0;
      window.coreAudioElement.play().catch(()=>{});
    } else {
      nextTrack();
    }
  });
}

function updateAllPlayButtons(isPlaying) {
  const miniPlay = document.getElementById('glass-mini-play-btn');
  if (miniPlay) miniPlay.textContent = isPlaying ? '⏸' : '▶';

  const modalPlayIcon = document.getElementById('glass-modal-play-icon');
  if (modalPlayIcon) modalPlayIcon.textContent = isPlaying ? '❚❚' : '▶';

  const modalPlayBtn = document.getElementById('glass-modal-play-btn');
  if (modalPlayBtn && !modalPlayIcon) modalPlayBtn.textContent = isPlaying ? '❚❚' : '▶';

  const playSvg = document.getElementById('glass-modal-play-svg');
  const pauseSvg = document.getElementById('glass-modal-pause-svg');
  if (playSvg && pauseSvg) {
    if (isPlaying) {
      playSvg.style.display = 'none';
      pauseSvg.style.display = 'block';
    } else {
      playSvg.style.display = 'block';
      pauseSvg.style.display = 'none';
    }
  }
}

function playTrackByIndex(idx) {
  if (idx < 0) idx = FULL_KATHA_PLAYLIST.length - 1;
  if (idx >= FULL_KATHA_PLAYLIST.length) idx = 0;

  currentKathaTrackIndex = idx;
  const track = FULL_KATHA_PLAYLIST[idx];
  if (!track) return;

  // Update Mini Player Texts
  const miniTitle = document.getElementById('glass-mini-title');
  if (miniTitle) miniTitle.textContent = track.title;

  const miniDeity = document.getElementById('glass-mini-deity');
  if (miniDeity) miniDeity.textContent = track.deity;

  const miniCover = document.getElementById('glass-mini-cover');
  if (miniCover) miniCover.src = track.img;

  // Update Full Modal Texts & Artwork
  const modalTitle = document.getElementById('glass-modal-title');
  if (modalTitle) modalTitle.textContent = track.title;

  const modalSub = document.getElementById('glass-modal-sub');
  if (modalSub) modalSub.textContent = track.sub;

  const modalImg = document.getElementById('glass-modal-img');
  if (modalImg) modalImg.src = track.img;

  // Fill Lyrics Drawer
  const lyricsContent = document.getElementById('glass-lyrics-content');
  if (lyricsContent) {
    lyricsContent.innerHTML = `<div style="font-size:0.95rem; line-height:1.8; color:#FDE68A; white-space:pre-line;">${track.lyrics}\n\n<span style="color:#FFF;">📖 विवरण:\n${track.desc}</span></div>`;
  }

  const diskHalo = document.querySelector('.glass-disk-halo');
  const scrubBox = document.querySelector('.glass-scrub-box');

  // DUAL-MODE ROUTING
  if (window.MediaRouter && window.MediaRouter.isYouTubeUrl(track.src)) {
    // MODE 2: YouTube Video
    if (diskHalo) diskHalo.style.display = 'none';
    if (scrubBox) scrubBox.style.display = 'none';

    const mTot = document.getElementById('glass-modal-tot-time');
    if (mTot) mTot.textContent = 'YouTube Stream';

    window.MediaRouter.loadYouTubePlayer(track.src, 'glass-youtube-container', {
      title: track.title,
      deity: track.deity
    });
    updateAllPlayButtons(true);
  } else {
    // MODE 1: Local MP3 Audio
    if (window.MediaRouter) window.MediaRouter.destroyYouTubePlayer();
    if (diskHalo) diskHalo.style.display = '';
    if (scrubBox) scrubBox.style.display = '';

    const audio = window.coreAudioElement;
    if (audio && track.src) {
      audio.src = track.src;
      audio.load();

      // Reset timeline displays immediately to track duration
      const mCur = document.getElementById('glass-modal-cur-time');
      if (mCur) mCur.textContent = '00:00';

      const mTot = document.getElementById('glass-modal-tot-time');
      if (mTot) mTot.textContent = formatAudioDuration(track.durationSecs);

      const seek = document.getElementById('glass-modal-seekbar');
      if (seek) seek.value = 0;

      audio.play().then(() => {
        updateAllPlayButtons(true);
        showToast(`🎵 बज रहा है: ${track.title}`);
      }).catch(e => {
        console.warn("Autoplay notice:", e);
        updateAllPlayButtons(false);
      });
    }
  }
}

function playKathaAudio(kathaId) {
  const idx = FULL_KATHA_PLAYLIST.findIndex(item => item.kathaId === kathaId);
  if (idx !== -1) {
    playTrackByIndex(idx);
  } else {
    playTrackByIndex(0);
  }
  openGlassPlayer();
}

function togglePlayKatha() {
  const audio = window.coreAudioElement;
  if (!audio.paused) {
    audio.pause();
    updateAllPlayButtons(false);
  } else {
    audio.play().then(() => {
      updateAllPlayButtons(true);
    }).catch(e => {
      console.warn("Play error:", e);
    });
  }
}

function prevTrack() {
  playTrackByIndex(currentKathaTrackIndex - 1);
}

function nextTrack() {
  if (isAudioShuffleMode) {
    const r = Math.floor(Math.random() * FULL_KATHA_PLAYLIST.length);
    playTrackByIndex(r);
  } else {
    playTrackByIndex(currentKathaTrackIndex + 1);
  }
}

function toggleShuffle() {
  isAudioShuffleMode = !isAudioShuffleMode;
  const btn = document.getElementById('glass-shuffle-btn');
  if (btn) {
    btn.classList.toggle('active', isAudioShuffleMode);
  }
  showToast(isAudioShuffleMode ? '🔀 शफल सक्रिय' : '🔀 शफल बंद');
}

function toggleRepeat() {
  isAudioRepeatMode = !isAudioRepeatMode;
  const btn = document.getElementById('glass-repeat-btn');
  if (btn) {
    btn.classList.toggle('active', isAudioRepeatMode);
  }
  showToast(isAudioRepeatMode ? '🔁 दोहराव सक्रिय' : '🔁 दोहराव बंद');
}

function seekAudio(val) {
  const audio = window.coreAudioElement;
  const track = FULL_KATHA_PLAYLIST[currentKathaTrackIndex] || FULL_KATHA_PLAYLIST[0];
  const dur = (!isNaN(audio.duration) && audio.duration > 0) ? audio.duration : (track.durationSecs || 300);
  const targetTime = (parseFloat(val) / 100) * dur;
  
  if (audio) {
    audio.currentTime = targetTime;
  }

  // Update displays immediately
  const mCur = document.getElementById('glass-modal-cur-time');
  if (mCur) mCur.textContent = formatAudioDuration(targetTime);

  const miniTime = document.getElementById('glass-mini-time');
  if (miniTime) miniTime.textContent = `${formatAudioDuration(targetTime)} / ${formatAudioDuration(dur)}`;
}

function openGlassPlayer() {
  const modal = document.getElementById('glass-full-player-modal');
  if (modal) {
    modal.classList.add('open');
    modal.style.display = 'flex';
    modal.style.opacity = '1';
    modal.style.pointerEvents = 'auto';
    modal.style.transform = 'translateY(0)';
  }
}

function closeGlassPlayer() {
  const modal = document.getElementById('glass-full-player-modal');
  if (modal) {
    modal.classList.remove('open');
    modal.style.display = 'none';
    modal.style.opacity = '0';
    modal.style.pointerEvents = 'none';
    modal.style.transform = 'translateY(100%)';
  }
  if (window.MediaRouter && window.MediaRouter.activeMode === 'youtube') {
    window.MediaRouter.destroyYouTubePlayer();
  }
}

