// 🔍 GLOBAL FULL-TEXT SEARCH SYSTEM (SQLite FTS5 + BM25 RANKING)
// Searches across ALL 10,010 records in Hindi & English with category filtering
// ══════════════════════════════════════════════════════════════════════════════

// ══════════════════════════════════════════════════════════════════════════════
// 🎧 BHAKTI AUDIO LIBRARY SYSTEM (78 PLAYABLE ITEMS: 38 MP3 + 40 YOUTUBE)
// Unified discovery, filtering, search, and dual-mode player integration
// ══════════════════════════════════════════════════════════════════════════════

let AUDIO_LIBRARY_ITEMS = [];
let currentAudioCategory = 'all';
let currentAudioSource = 'all';
let currentAudioQuery = '';
let currentAudioIndex = 0;
let audioSearchDebounceTimer = null;

function getDeityArtwork(deityStr, titleStr) {
  const combined = ((deityStr || '') + ' ' + (titleStr || '')).toLowerCase();
  if (combined.includes('hanuman') || combined.includes('हनुमान') || combined.includes('बजरंग')) return 'assets/deity_hanuman.jpg';
  if (combined.includes('shiv') || combined.includes('शिव') || combined.includes('भोले') || combined.includes('महादेव')) return 'assets/deity_shiv.jpg';
  if (combined.includes('krishna') || combined.includes('कृष्ण') || combined.includes('गोपाल') || combined.includes('गोविंद') || combined.includes('राधा')) return 'assets/deity_krishna.jpg';
  if (combined.includes('ram') || combined.includes('राम') || combined.includes('राघव') || combined.includes('रामायण')) return 'assets/deity_ramayana.jpg';
  if (combined.includes('durga') || combined.includes('दुर्गा') || combined.includes('वैष्णो') || combined.includes('काली') || combined.includes('गौरी')) return 'assets/deity_durga.jpg';
  if (combined.includes('ganesh') || combined.includes('गणेश') || combined.includes('विनायक') || combined.includes('संकष्टी')) return 'assets/deity_ganesh.jpg';
  if (combined.includes('lakshmi') || combined.includes('लक्ष्मी')) return 'assets/deity_lakshmi.jpg';
  if (combined.includes('saraswati') || combined.includes('सरस्वती')) return 'assets/deity_saraswati.jpg';
  if (combined.includes('vishnu') || combined.includes('विष्णु') || combined.includes('एकादशी') || combined.includes('सत्यनारायण')) return 'assets/deity_vishnu.jpg';
  if (combined.includes('shani') || combined.includes('शनि')) return 'assets/deity_shanidev.jpg';
  if (combined.includes('khatu') || combined.includes('खाटू') || combined.includes('बर्बरीक')) return 'assets/deity_khatushyam.jpg';
  if (combined.includes('rajan') || combined.includes('राजन')) return 'assets/speaker_rajan.jpg';
  if (combined.includes('indresh') || combined.includes('इंद्रेश')) return 'assets/speaker_indresh.jpg';
  return 'assets/app_logo.jpg';
}

function formatTypeBadge(type) {
  switch (type) {
    case 'aarti': return '🪔 आरती';
    case 'chalisa': return '📜 चालीसा';
    case 'bhajan': return '🎵 भजन';
    case 'katha': return '📖 कथा';
    case 'mantra': return '🕉️ मंत्र';
    case 'stotram': return '🌺 स्तोत्र';
    case 'vrat_katha': return '🚩 व्रत कथा';
    case 'satsang': return '🎙️ सत्संग';
    case 'naam_jaap': return '📿 नाम जाप';
    case 'festival_special': return '✨ पर्व विशेष';
    case 'dharmik_gyan': return '💡 ज्ञान';
    case 'chetawani_bhajan': return '🔔 चेतावनी';
    case 'temple_katha': return '🏛️ मंदिर कथा';
    default: return '✨ ' + (type || 'भक्ति');
  }
}

async function renderAudioLibrary(category, source, query) {
  const grid = document.getElementById('katha-grid');
  if (!grid) return;

  currentAudioCategory = category || currentAudioCategory || 'all';
  currentAudioSource = source || currentAudioSource || 'all';
  currentAudioQuery = (typeof query === 'string' ? query : (document.getElementById('audio-search')?.value || '')).trim();

  grid.innerHTML = `
    <div style="grid-column:1/-1; text-align:center; padding:3rem 1rem; color:rgba(255,255,255,0.7);">
      <div style="font-size:2.2rem; margin-bottom:0.8rem; animation:spin 1.5s linear infinite;">⏳</div>
      <p style="font-size:1.05rem; font-weight:700; color:#FDE68A;">ऑडियो लोड हो रहे हैं…</p>
    </div>
  `;

  try {
    const params = new URLSearchParams();
    if (currentAudioQuery) params.set('q', currentAudioQuery);
    if (currentAudioCategory && currentAudioCategory !== 'all') params.set('type', currentAudioCategory);
    if (currentAudioSource && currentAudioSource !== 'all') params.set('source', currentAudioSource);
    params.set('limit', '100');

    const resp = await fetch(`/api/audio-library?${params.toString()}`);
    if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
    const data = await resp.json();
    AUDIO_LIBRARY_ITEMS = data.items || [];
    window.AUDIO_LIBRARY_ITEMS = AUDIO_LIBRARY_ITEMS;

    if (AUDIO_LIBRARY_ITEMS.length === 0) {
      grid.innerHTML = `
        <div style="grid-column:1/-1; text-align:center; padding:3rem 1rem; color:rgba(255,255,255,0.7);">
          <div style="font-size:3rem; margin-bottom:1rem;">🎧</div>
          <p style="font-size:1.15rem; font-weight:700; color:#FDE68A;">कोई ऑडियो नहीं मिला</p>
          <p style="font-size:0.88rem; color:#E2E8F0; margin-top:0.3rem;">कृपया दूसरा शब्द खोजें या श्रेणी/स्रोत बदलें</p>
        </div>
      `;
      return;
    }

    grid.innerHTML = AUDIO_LIBRARY_ITEMS.map((item, idx) => {
      const typeBadge = formatTypeBadge(item.content_type);
      const sourceBadge = '<span style="background:rgba(248,200,59,0.18); border:1px solid rgba(248,200,59,0.4); color:#FDE68A; font-size:0.72rem; font-weight:800; padding:3px 8px; border-radius:8px;">✨ दिव्य संगीत</span>';
      
      const thumb = getDeityArtwork(item.deity_id || item.deity_name_hi, item.title);
      const excerpt = (item.content_text || item.short_desc || 'पावन भक्ति रस।').substring(0, 110).replace(/\n/g, ' ');

      return `
        <div class="katha-card-luxury" onclick="openReaderFromAudioLib(${idx})" style="cursor:pointer; display:flex; flex-direction:column; justify-content:space-between; transition:transform 0.2s ease, box-shadow 0.2s ease; border:1px solid rgba(248,200,59,0.25);">
          <div class="katha-card-body" style="width:100%; padding:14px 16px;">
            <div style="display:flex; gap:12px; margin-bottom:0.8rem; align-items:center;">
              <img src="${thumb}" alt="${item.title}" style="width:54px; height:54px; border-radius:14px; object-fit:cover; border:1.5px solid #FDE68A; flex-shrink:0; box-shadow:0 4px 10px rgba(0,0,0,0.5);" onerror="this.src='assets/app_logo.jpg'" />
              <div style="flex:1; min-width:0;">
                <div style="display:flex; gap:6px; flex-wrap:wrap; margin-bottom:4px;">
                  <span style="background:rgba(248,200,59,0.2); color:#FDE68A; padding:2px 8px; border-radius:6px; font-size:0.75rem; font-weight:700;">${typeBadge}</span>
                  ${sourceBadge}
                </div>
                <h3 style="font-size:1.02rem; color:#FFFDF8; font-weight:800; line-height:1.35; white-space:nowrap; overflow:hidden; text-overflow:ellipsis; margin:0;">${item.title}</h3>
              </div>
            </div>

            <p style="font-size:0.82rem; color:#CBD5E1; line-height:1.5; margin-bottom:0.8rem; display:-webkit-box; -webkit-line-clamp:2; -webkit-box-orient:vertical; overflow:hidden;">
              ${excerpt}...
            </p>

            <div style="display:flex; justify-content:space-between; align-items:center; border-top:1px solid rgba(255,255,255,0.1); padding-top:10px;">
              <button class="katha-card-play-btn" onclick="event.stopPropagation(); playAudioLibraryIndex(${idx})" style="padding:7px 16px; font-size:0.85rem; border-radius:12px; background:linear-gradient(135deg, #F8C83B, #D97706); color:#110526; font-weight:900; border:none; cursor:pointer; box-shadow:0 3px 10px rgba(248,200,59,0.35); display:inline-flex; align-items:center; gap:6px;">
                <span>▶</span> सुनें
              </button>
              <button onclick="event.stopPropagation(); openReaderFromAudioLib(${idx})" style="padding:6px 12px; font-size:0.78rem; border-radius:10px; background:rgba(255,255,255,0.08); border:1px solid rgba(255,255,255,0.2); color:#E2E8F0; font-weight:700; cursor:pointer;">
                📖 पाठ
              </button>
            </div>
          </div>
        </div>
      `;
    }).join('');
  } catch (err) {
    console.error("Audio Library fetch error:", err);
    grid.innerHTML = `
      <div style="grid-column:1/-1; text-align:center; padding:3rem 1rem; color:#EF4444;">
        <p>⚠️ ऑडियो लोड करने में त्रुटि: ${err.message}</p>
      </div>
    `;
  }
}

function playAudioLibraryIndex(idx) {
  const items = (window.AUDIO_LIBRARY_ITEMS && window.AUDIO_LIBRARY_ITEMS.length) ? window.AUDIO_LIBRARY_ITEMS : AUDIO_LIBRARY_ITEMS;
  if (!items || idx < 0 || idx >= items.length) return;
  currentAudioIndex = idx;
  window.currentAudioIndex = idx;
  const item = items[idx];
  if (!item) return;

  const thumb = getDeityArtwork(item.deity_id || item.deity_name_hi, item.title);

  // Update Mini Player
  const miniTitle = document.getElementById('glass-mini-title');
  if (miniTitle) miniTitle.textContent = item.title;
  const miniDeity = document.getElementById('glass-mini-deity');
  if (miniDeity) miniDeity.textContent = item.deity_name_hi || item.deity_id || 'भक्ति रस';
  const miniCover = document.getElementById('glass-mini-cover');
  if (miniCover) miniCover.src = thumb;

  // Update Full Glass Modal
  const modalTitle = document.getElementById('glass-modal-title');
  if (modalTitle) modalTitle.textContent = item.title;
  const modalSub = document.getElementById('glass-modal-sub');
  if (modalSub) modalSub.textContent = `${item.deity_name_hi || item.deity_id || 'सनातन'} • ${formatTypeBadge(item.content_type)}`;
  const modalImg = document.getElementById('glass-modal-img');
  if (modalImg) modalImg.src = thumb;

  const lyricsContent = document.getElementById('glass-lyrics-content');
  if (lyricsContent) {
    lyricsContent.innerHTML = `<div style="font-size:0.95rem; line-height:1.8; color:#FDE68A; white-space:pre-line;">${item.content_text || 'पावन भक्ति रस'}\n\n<span style="color:#FFF;">📖 स्रोत: ${item.audio_url && item.audio_url.startsWith('assets/audio/') ? '💾 ऑफ़लाइन MP3' : '🎬 YouTube HD'}</span></div>`;
  }

  // Play via unified MediaRouter
  if (window.MediaRouter) {
    window.MediaRouter.playRecord(item, 'glass');
  }
}

function openReaderFromAudioLib(idx) {
  const items = (window.AUDIO_LIBRARY_ITEMS && window.AUDIO_LIBRARY_ITEMS.length) ? window.AUDIO_LIBRARY_ITEMS : AUDIO_LIBRARY_ITEMS;
  if (!items || idx < 0 || idx >= items.length) return;
  const item = items[idx];
  if (typeof window.openReaderFromAudioLib === 'function') {
    window.openReaderFromAudioLib(idx);
  } else {
    openReader(item, 'page-katha');
  }
}

function playRandomAudioItem() {
  if (AUDIO_LIBRARY_ITEMS.length === 0) return;
  const randIdx = Math.floor(Math.random() * AUDIO_LIBRARY_ITEMS.length);
  playAudioLibraryIndex(randIdx);
}

function filterAudioSource(source, btnEl) {
  currentAudioSource = source;
  document.querySelectorAll('.audio-source-tab-btn').forEach(b => {
    b.classList.remove('active');
    b.style.background = 'rgba(255,255,255,0.08)';
    b.style.color = '#FFF';
    b.style.borderColor = 'rgba(255,255,255,0.2)';
  });
  if (btnEl) {
    btnEl.classList.add('active');
    btnEl.style.background = 'linear-gradient(135deg, #F8C83B, #D97706)';
    btnEl.style.color = '#110526';
    btnEl.style.borderColor = 'rgba(248,200,59,0.5)';
  }
  renderAudioLibrary(currentAudioCategory, currentAudioSource, currentAudioQuery);
}

function filterAudioCategory(cat, btnEl) {
  currentAudioCategory = cat;
  document.querySelectorAll('#audio-filter-tabs .katha-tab-btn').forEach(b => b.classList.remove('active'));
  if (btnEl) {
    btnEl.classList.add('active');
  }
  renderAudioLibrary(currentAudioCategory, currentAudioSource, currentAudioQuery);
}

function nextTrack() {
  if (AUDIO_LIBRARY_ITEMS.length > 0) {
    let nextIdx = (currentAudioIndex + 1) % AUDIO_LIBRARY_ITEMS.length;
    playAudioLibraryIndex(nextIdx);
  }
}

function prevTrack() {
  if (AUDIO_LIBRARY_ITEMS.length > 0) {
    let prevIdx = (currentAudioIndex - 1 + AUDIO_LIBRARY_ITEMS.length) % AUDIO_LIBRARY_ITEMS.length;
    playAudioLibraryIndex(prevIdx);
  }
}

function initAudioLibraryPage() {
  window.initKathaPage = initAudioLibraryPage;
  const searchInput = document.getElementById('audio-search');
  if (searchInput && !searchInput.dataset.bound) {
    searchInput.dataset.bound = 'true';
    searchInput.addEventListener('input', (e) => {
      clearTimeout(audioSearchDebounceTimer);
      audioSearchDebounceTimer = setTimeout(() => {
        renderAudioLibrary(currentAudioCategory, currentAudioSource, e.target.value);
      }, 250);
    });
  }
  renderAudioLibrary(currentAudioCategory, currentAudioSource, searchInput ? searchInput.value : '');
}

// Backwards compatibility alias
window.renderKathaGrid = renderAudioLibrary;
window.filterKathaCategory = filterAudioCategory;
window.initKathaPage = initAudioLibraryPage;
window.initAudioLibraryPage = initAudioLibraryPage;
window.playAudioLibraryIndex = playAudioLibraryIndex;
window.playRandomAudioItem = playRandomAudioItem;
window.filterAudioSource = filterAudioSource;
window.filterAudioCategory = filterAudioCategory;

