function updateMiniPlayerVisibility(currentPageId) {
  const gMini = document.getElementById('glass-mini-player');
  const legacyMini = document.getElementById('mini-player');
  
  if (currentPageId === 'page-katha') {
    if (window.isAudioPlaying || (window.coreAudioElement && window.coreAudioElement.src)) {
      if (gMini) {
        gMini.classList.remove('hidden');
        gMini.style.display = 'flex';
      }
    }
  } else {
    if (gMini) {
      gMini.classList.add('hidden');
      gMini.style.display = 'none';
    }
    if (legacyMini) {
      legacyMini.classList.add('hidden');
      legacyMini.style.display = 'none';
    }
  }
}

var _prevShowPage1 = window.showPage;
window.showPage = function(pageId) {
  if (typeof _prevShowPage1 === 'function') {
    _prevShowPage1(pageId);
  }
  updateMiniPlayerVisibility(pageId);
  if (pageId === 'page-katha') {
    initKathaPage();
  }
};

var _prevNavTo1 = window.navigateTo;
window.navigateTo = function(pageId) {
  if (typeof _prevNavTo1 === 'function') {
    _prevNavTo1(pageId);
  }
  updateMiniPlayerVisibility(pageId);
  if (pageId === 'page-katha') {
    initKathaPage();
  }
};

document.addEventListener('DOMContentLoaded', () => {
  setTimeout(initKathaPage, 100);
  document.querySelectorAll('.nav-btn, .bottom-nav button').forEach(btn => {
    btn.addEventListener('click', () => {
      const pageId = btn.dataset.page || btn.getAttribute('data-page');
      if (pageId) {
        updateMiniPlayerVisibility(pageId);
      }
    });
  });
});

