function openAartiCollectionModal(deityKey) {
  const coll = window.AARTI_COLLECTIONS[deityKey];
  if (!coll) return;

  const modal = document.getElementById('aarti-options-modal');
  if (!modal) return;

  document.getElementById('aarti-modal-title').textContent = coll.title;
  document.getElementById('aarti-modal-deity').textContent = coll.deity;
  document.getElementById('aarti-modal-mantra').textContent = coll.mantra;
  
  const imgEl = document.getElementById('aarti-modal-img');
  if (imgEl) {
    imgEl.src = coll.img;
    imgEl.onerror = function() { this.src = coll.fallbackImg; };
  }

  const listContainer = document.getElementById('aarti-modal-list');
  if (listContainer) {
    listContainer.innerHTML = coll.items.map((item, idx) => `
      <div class="aarti-opt-card" onclick="openAartiItemDirect('${deityKey}', ${idx})">
        <div class="aarti-opt-index">0${idx+1}</div>
        <div class="aarti-opt-info">
          <div class="aarti-opt-title">${item.title}</div>
          <div class="aarti-opt-sub">${item.sub}</div>
        </div>
        <div class="aarti-opt-actions">
          <button class="aarti-opt-read-btn" onclick="event.stopPropagation(); readAartiItemDirect('${deityKey}', ${idx})" title="पाठ पढ़ें">
            📖 पढ़ें
          </button>
          <button class="aarti-opt-play-btn" onclick="event.stopPropagation(); playAartiItemDirect('${deityKey}', ${idx})" title="आरती सुनें">
            ▶
          </button>
        </div>
      </div>
    `).join('');
  }

  modal.style.display = 'flex';
  modal.style.opacity = '1';
  modal.style.pointerEvents = 'auto';

  if (navigator.vibrate) navigator.vibrate(25);
}

function closeAartiOptionsModal() {
  const modal = document.getElementById('aarti-options-modal');
  if (modal) modal.style.display = 'none';
}

function openAartiItemDirect(deityKey, idx) {
  if (typeof window.readAartiItemDirect === 'function') {
    window.readAartiItemDirect(deityKey, idx);
  }
}

function readAartiItemDirect(deityKey, idx) {
  if (typeof window.readAartiItemDirect === 'function' && window.readAartiItemDirect !== readAartiItemDirect) {
    return window.readAartiItemDirect(deityKey, idx);
  }
}

function playAartiItemDirect(deityKey, idx) {
  if (typeof window.playAartiItemDirect === 'function' && window.playAartiItemDirect !== playAartiItemDirect) {
    return window.playAartiItemDirect(deityKey, idx);
  }
}


// Aarti Deity Grid Click Interceptor for Multi-Aarti Options
var _prevBuildDeityGrid = window.buildDeityGrid;
window.buildDeityGrid = function(containerId, items, contentPrefix, fromPage) {
  const container = document.getElementById(containerId);
  if (!container) return;
  container.innerHTML = '';
  items.forEach(d => {
    const card = document.createElement('button');
    card.className = 'deity-card';
    const imgHtml = d.img 
      ? `<img src="${d.img}" alt="${d.name}" class="deity-card-img" onerror="this.style.display='none';this.nextElementSibling.style.display='flex'" /><div class="deity-card-emoji" style="display:none">${d.emoji || '🕉️'}</div>`
      : `<div class="deity-card-emoji">${d.emoji || '🕉️'}</div>`;
    
    card.innerHTML = `${imgHtml}<span class="deity-card-name">${d.name}</span>`;
    
    card.addEventListener('click', () => {
      if (contentPrefix === 'aarti') {
        if (d.id === 'ganesh' || d.id === 'ganesha') {
          openAartiCollectionModal('ganesh');
          return;
        }
        if (d.id === 'hanuman') {
          openAartiCollectionModal('hanuman');
          return;
        }
      }
      const contentKey = d.contentKey || (contentPrefix + '_' + d.id);
      openReader(contentKey, fromPage);
    });
    container.appendChild(card);
  });
};

window.finishOnboarding = function() {
  try { localStorage.setItem('bhakti_onboarded', 'true'); } catch(e) {}
  const ob = document.getElementById('onboarding-overlay');
  if (ob) {
    ob.style.opacity = '0';
    ob.style.transition = 'opacity 0.3s ease';
    setTimeout(() => { 
      ob.style.display = 'none'; 
      ob.classList.add('hidden');
    }, 300);
  }
  if (typeof showPage === 'function') {
    showPage('page-home');
  }
};

window.nextOnboardingSlide = function() {
  if (currentOnboardingSlide < totalOnboardingSlides - 1) {
    currentOnboardingSlide++;
    updateOnboardingSlide();
  } else {
    finishOnboarding();
  }
};

window.initOnboarding = function() {
  const isDone = localStorage.getItem('bhakti_onboarded');
  const ob = document.getElementById('onboarding-overlay');
  if (isDone === 'true') {
    if (ob) {
      ob.style.display = 'none';
      ob.classList.add('hidden');
      ob.style.pointerEvents = 'none';
    }
    showPage('page-home');
    return;
  }
  currentOnboardingSlide = 0;
  if (ob) {
    ob.classList.remove('hidden');
    ob.style.display = 'flex';
    ob.style.pointerEvents = 'auto';
    ob.style.opacity = '1';
    updateOnboardingSlide();
  }
};

window.finishOnboarding = function() {
  try { localStorage.setItem('bhakti_onboarded', 'true'); } catch(e) {}
  const ob = document.getElementById('onboarding-overlay');
  if (ob) {
    ob.style.opacity = '0';
    ob.style.pointerEvents = 'none';
    setTimeout(() => { 
      ob.style.display = 'none'; 
      ob.classList.add('hidden');
    }, 300);
  }
  const authModal = document.getElementById('auth-modal');
  if (authModal) {
    authModal.style.display = 'none';
    authModal.classList.add('hidden');
    authModal.style.pointerEvents = 'none';
  }
  showPage('page-home');
};

window.closeAuthModal = function() {
  const authModal = document.getElementById('auth-modal');
  if (authModal) {
    authModal.style.display = 'none';
    authModal.classList.add('hidden');
    authModal.style.pointerEvents = 'none';
  }
};

// ══════════════════════════════════════════════════════════════════════════════
// 🚀 MASTER APP CONTROLLER: ONBOARDING, NAVIGATION & CLICK DISPATCHER
// ══════════════════════════════════════════════════════════════════════════════

window.currentOnboardingSlide = 0;
window.totalOnboardingSlides = 5;

window.initOnboarding = function() {
  window.currentOnboardingSlide = 0;
  const ob = document.getElementById('onboarding-overlay');
  if (ob) {
    ob.classList.remove('hidden');
    ob.style.display = 'flex';
    ob.style.opacity = '1';
    ob.style.visibility = 'visible';
    ob.style.pointerEvents = 'auto';
    window.updateOnboardingSlide();
  }
};

window.updateOnboardingSlide = function() {
  const track = document.getElementById('onboarding-track');
  const dots = document.querySelectorAll('.onboarding-dot');
  const nextBtn = document.getElementById('onboarding-next-btn');

  if (track) {
    track.style.transform = `translateX(-${window.currentOnboardingSlide * 100}vw)`;
  }

  dots.forEach((d, i) => {
    if (i === window.currentOnboardingSlide) d.classList.add('active');
    else d.classList.remove('active');
  });

  if (nextBtn) {
    nextBtn.textContent = window.currentOnboardingSlide === window.totalOnboardingSlides - 1 ? 'आरंभ करें ❯' : 'आगे बढ़ें ❯';
  }
};

window.nextOnboardingSlide = function() {
  if (window.currentOnboardingSlide < window.totalOnboardingSlides - 1) {
    window.currentOnboardingSlide++;
    window.updateOnboardingSlide();
  } else {
    window.finishOnboarding();
  }
};

window.finishOnboarding = function() {
  try { localStorage.setItem('bhakti_onboarded', 'true'); } catch(e) {}
  const ob = document.getElementById('onboarding-overlay');
  if (ob) {
    ob.style.opacity = '0';
    ob.style.pointerEvents = 'none';
    setTimeout(() => {
      ob.style.display = 'none';
      ob.classList.add('hidden');
    }, 350);
  }
  const auth = document.getElementById('auth-modal');
  if (auth) {
    auth.style.display = 'none';
    auth.classList.add('hidden');
    auth.style.pointerEvents = 'none';
  }
  window.showPage('page-home');
};

window.replayOnboarding = function() {
  window.initOnboarding();
};

