// ══════════════════════════════════════════════════════════════════════════════
// 🚀 MASTER UNIFIED NAVIGATION ROUTER (WINDOW.SHOWPAGE)
// ══════════════════════════════════════════════════════════════════════════════

window.showPage = function(pageId) {
  if (!pageId) return;
  
  // Normalize pageId
  if (!pageId.startsWith('page-')) {
    pageId = 'page-' + pageId;
  }

  const targetPage = document.getElementById(pageId);
  if (!targetPage) {
    console.warn('Page element not found:', pageId);
    return;
  }

  // 1. Switch active page
  document.querySelectorAll('.page').forEach(p => p.classList.remove('active'));
  targetPage.classList.add('active');
  try { currentPage = pageId; } catch(e) {}
  window.currentPage = pageId;

  // 2. Update Bottom Nav active state & Curved Fluid Dock
  if (typeof window.updateCurvedBottomNav === 'function') {
    window.updateCurvedBottomNav(pageId);
  }

  // Hide Bottom Navigation in Epic Games, Reader, and 3D Mandir
  if (pageId === 'page-epic-games' || pageId === 'page-reader' || pageId === 'page-3d-mandir') {
    document.body.classList.add('in-epic-games');
    const navEl = document.getElementById('curved-fluid-bottom-nav');
    if (navEl) {
      navEl.classList.add('nav-hidden');
      navEl.style.setProperty('display', 'none', 'important');
      navEl.style.setProperty('opacity', '0', 'important');
      navEl.style.setProperty('visibility', 'hidden', 'important');
      navEl.style.setProperty('pointer-events', 'none', 'important');
      navEl.style.setProperty('transform', 'translate(-50%, 200%)', 'important');
    }
    document.querySelectorAll('.curved-fluid-bottom-nav, .app-bottom-nav, .bottom-nav').forEach(el => {
      el.classList.add('nav-hidden');
      el.style.setProperty('display', 'none', 'important');
      el.style.setProperty('opacity', '0', 'important');
      el.style.setProperty('visibility', 'hidden', 'important');
      el.style.setProperty('pointer-events', 'none', 'important');
    });
  } else {
    document.body.classList.remove('in-epic-games');
    const navEl = document.getElementById('curved-fluid-bottom-nav');
    if (navEl) {
      navEl.classList.remove('nav-hidden');
      navEl.style.removeProperty('display');
      navEl.style.removeProperty('opacity');
      navEl.style.removeProperty('visibility');
      navEl.style.removeProperty('pointer-events');
      navEl.style.removeProperty('transform');
    }
    document.querySelectorAll('.curved-fluid-bottom-nav, .app-bottom-nav, .bottom-nav').forEach(el => {
      el.classList.remove('nav-hidden');
      el.style.removeProperty('display');
      el.style.removeProperty('opacity');
      el.style.removeProperty('visibility');
      el.style.removeProperty('pointer-events');
    });
  }

  document.querySelectorAll('.app-bottom-nav .nav-item, .bottom-nav .nav-item, .bottom-nav-btn, .nav-item').forEach(btn => {
    const p = btn.dataset.page || btn.getAttribute('data-page');
    if (p === pageId) {
      btn.classList.add('active');
    } else {
      btn.classList.remove('active');
    }
  });

  // 3. Update Header title if applicable
  const titles = {
    'page-home': 'भक्ति में लीन',
    'page-bhajan': 'भजन संग्रह',
    'page-aarti': 'नित्य आरती',
    'page-mantra': 'दिव्य मंत्र',
    'page-chalisa': 'श्री चालीसा',
    'page-desh': 'देशभक्ति',
    'page-ramayana': 'रामायण',
    'page-profile': 'प्रोफ़ाइल',
    'page-settings': 'सेटिंग्स',
    'page-about': 'हमारे बारे में',
    'page-downloads': 'डाउनलोड्स',
    'page-reader': 'पावन पाठ',
    'page-calendar': 'हिन्दी कैलेंडर',
    'page-english-calendar': 'अंग्रेजी कैलेंडर',
    'page-katha': 'ऑडियो लाइब्रेरी',
    'page-achievements': 'उपलब्धियां',
    'page-panchang': 'दैनिक पंचांग',
    'page-month-panchang': 'मासिक पंचांग',
    'page-muhurat': 'शुभ मुहूर्त',
    'page-vrat-detail': 'व्रत विवरण',
    'page-jar': 'भक्ति अमृत कलश',
    'page-mala': 'जाप माला',
    'page-gallery': 'पावन दिव्य गैलरी',
    'page-top10': 'शीर्ष 10 भक्ति'
  };
  const headerTitleEl = document.querySelector('.header-title');
  if (headerTitleEl && titles[pageId]) {
    headerTitleEl.textContent = titles[pageId];
  }

  // 4. Scroll to top
  window.scrollTo(0, 0);

  // 5. Page specific hooks
  if (pageId === 'page-gallery' && typeof renderDivineGallery === 'function') {
    setTimeout(renderDivineGallery, 20);
  }
  if (pageId === 'page-katha' && typeof initKathaPage === 'function') {
    initKathaPage();
  }
  if (pageId === 'page-calendar' && typeof renderCalGrid === 'function' && typeof calYear !== 'undefined' && typeof calMonth !== 'undefined') {
    renderCalGrid(calYear, calMonth);
  }
  if (typeof updateMiniPlayerVisibility === 'function') {
    updateMiniPlayerVisibility(pageId);
  }

  // 6. Dispatch page change event
  document.dispatchEvent(new CustomEvent('bhakti-page-change', { detail: pageId }));
};

window.navigateTo = window.showPage;

// ══════════════════════════════════════════════════════════════════════════════
// 🌟 BULLETPROOF ONBOARDING & AUTH CONTROLLER
// ══════════════════════════════════════════════════════════════════════════════

window.currentOnboardingSlide = 0;
window.totalOnboardingSlides = 5;
window.currentAuthTab = 'login';

window.initOnboarding = function() {
  const isDone = localStorage.getItem('bhakti_onboarded');
  const ob = document.getElementById('onboarding-overlay');
  
  if (isDone === 'true') {
    if (ob) {
      ob.style.display = 'none';
      ob.classList.add('hidden');
    }
    window.showPage('page-home');
    return;
  }

  window.currentOnboardingSlide = 0;
  if (ob) {
    ob.classList.remove('hidden');
    ob.style.display = 'flex';
    ob.style.opacity = '1';
    ob.style.pointerEvents = 'auto';
    window.updateOnboardingSlide();
  }
};

window.updateOnboardingSlide = function() {
  const track = document.getElementById('onboarding-track');
  const dots = document.querySelectorAll('.onboarding-dot');
  const nextBtn = document.getElementById('onboarding-next-btn');

  if (track) {
    track.style.transform = `translateX(-${window.currentOnboardingSlide * 100}vw)`;
  }

  dots.forEach((d, i) => {
    if (i === window.currentOnboardingSlide) d.classList.add('active');
    else d.classList.remove('active');
  });

  if (nextBtn) {
    nextBtn.textContent = window.currentOnboardingSlide === window.totalOnboardingSlides - 1 ? 'आरंभ करें ❯' : 'आगे बढ़ें ❯';
  }
};

window.nextOnboardingSlide = function() {
  if (window.currentOnboardingSlide < window.totalOnboardingSlides - 1) {
    window.currentOnboardingSlide++;
    window.updateOnboardingSlide();
  } else {
    window.finishOnboarding();
  }
};

window.finishOnboarding = function() {
  try { localStorage.setItem('bhakti_onboarded', 'true'); } catch(e) {}
  
  // Fade out onboarding overlay
  const ob = document.getElementById('onboarding-overlay');
  if (ob) {
    ob.style.opacity = '0';
    ob.style.pointerEvents = 'none';
    setTimeout(() => {
      ob.style.display = 'none';
      ob.classList.add('hidden');
    }, 300);
  }

  // Open Auth Modal (Login / Signup Screen)
  window.openAuthModal();
};

window.openAuthModal = function() {
  const authModal = document.getElementById('auth-modal');
  if (authModal) {
    authModal.classList.remove('hidden');
    authModal.style.display = 'flex';
    authModal.style.opacity = '1';
    authModal.style.pointerEvents = 'auto';
  }
};

window.closeAuthModal = function() {
  const authModal = document.getElementById('auth-modal');
  if (authModal) {
    authModal.style.opacity = '0';
    authModal.style.pointerEvents = 'none';
    setTimeout(() => {
      authModal.style.display = 'none';
      authModal.classList.add('hidden');
    }, 300);
  }
  window.showPage('page-home');
};

window.switchAuthTab = function(tab) {
  window.currentAuthTab = tab;
  const loginBtn = document.getElementById('tab-login');
  const signupBtn = document.getElementById('tab-signup');
  const nameInput = document.getElementById('auth-name');
  const submitBtn = document.getElementById('auth-submit-btn');

  if (tab === 'login') {
    if (loginBtn) loginBtn.classList.add('active');
    if (signupBtn) signupBtn.classList.remove('active');
    if (nameInput) nameInput.style.display = 'none';
    if (submitBtn) submitBtn.textContent = 'प्रवेश करें';
  } else {
    if (signupBtn) signupBtn.classList.add('active');
    if (loginBtn) loginBtn.classList.remove('active');
    if (nameInput) nameInput.style.display = 'block';
    if (submitBtn) submitBtn.textContent = 'खाता बनाएं';
  }
};

window.submitAuth = function() {
  const emailInput = document.getElementById('auth-email');
  const nameInput = document.getElementById('auth-name');
  const email = emailInput ? emailInput.value : '';
  const name = nameInput && nameInput.value ? nameInput.value : 'भक्त जन';

  const user = { name, email: email || 'bhakt@bhakti.app', isLoggedIn: true };
  try { localStorage.setItem('bhakti_user', JSON.stringify(user)); } catch(e) {}
  
  if (typeof updateProfileUI === 'function') updateProfileUI();
  if (typeof showToast === 'function') showToast(`🙏 स्वागत है, ${name}!`);
  
  window.closeAuthModal();
};

window.continueAsGuest = function() {
  const user = { name: 'अतिथि भक्त', email: 'guest@bhakti.app', authType: 'guest', isGuest: true, isLoggedIn: false };
  try {
    localStorage.setItem('bhakti_user', JSON.stringify(user));
    localStorage.setItem('sanatan_auth_method', 'guest');
  } catch(e) {}
  
  if (typeof updateProfileUI === 'function') updateProfileUI();
  if (typeof showToast === 'function') showToast('🙏 जय श्री राम! आपका स्वागत है।');
  
  if (typeof window.dismissGuestLoginPrompt === 'function') {
    window.dismissGuestLoginPrompt();
  } else {
    window.closeAuthModal();
  }
};

window.continueWithGoogle = function() {
  if (typeof window.openGoogleAccountPickerModal === 'function') {
    window.openGoogleAccountPickerModal();
  }
};

window.replayOnboarding = function() {
  const ob = document.getElementById('onboarding-overlay');
  if (ob) {
    ob.classList.remove('hidden');
    ob.style.display = 'flex';
    ob.style.opacity = '1';
    ob.style.pointerEvents = 'auto';
    window.currentOnboardingSlide = 0;
    window.updateOnboardingSlide();
  }
};

// ══════════════════════════════════════════════════════════════════════════════
// ⚡ MASTER INSTANT APPLICATION INITIALIZER
// ══════════════════════════════════════════════════════════════════════════════

window.initAllAppModules = function() {
  console.log("⚡ Initializing Bhakti App Modules...");
  
  const fnNames = [
    'initNavigation', 'initDeityGrids', 'initPanchang', 'initCoverflow3D', 
    'initFestivals', 'initCalendar', 'initMuhuratPage', 'initReader', 
    'initDrawer', 'initPanchangPage', 'initKathaPage', 'initAudioLibraryPage',
    'renderDivineGallery'
  ];

  fnNames.forEach(fn => {
    try {
      if (typeof window[fn] === 'function') {
        window[fn]();
      } else if (typeof globalThis[fn] === 'function') {
        globalThis[fn]();
      }
    } catch(err) {
      console.warn('Module init warning for ' + fn, err);
    }
  });

  // Ensure Panchang data is populated immediately
  if (typeof renderTodayPanchang === 'function') {
    renderTodayPanchang();
  }
  if (typeof updatePanchangCard === 'function') {
    updatePanchangCard();
  }
};

// Global Delegation for all clickable elements
document.addEventListener('click', function(e) {
  // Check for data-page
  const pageTarget = e.target.closest('[data-page]');
  if (pageTarget) {
    const pageId = pageTarget.getAttribute('data-page');
    if (pageId) {
      window.showPage(pageId);
      return;
    }
  }

  // Check for back-btn
  const backTarget = e.target.closest('.back-btn, [data-back]');
  if (backTarget) {
    if (backTarget.closest('#page-reader') || window.currentPage === 'page-reader') {
      e.preventDefault();
      e.stopPropagation();
      if (typeof window.handleReaderBack === 'function') {
        window.handleReaderBack();
      } else {
        window.showPage(window.readerBackPage || 'page-home');
      }
      return;
    }
    const backPage = backTarget.dataset.back || window.readerBackPage || 'page-home';
    window.showPage(backPage);
    return;
  }
}, true);

// Execute on DOM ready
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', window.initAllAppModules);
} else {
  window.initAllAppModules();
}

window.addEventListener('load', function() {
  window.initAllAppModules();
  
  const splash = document.getElementById('splash-screen');
  setTimeout(function() {
    if (splash) {
      splash.style.opacity = '0';
      splash.style.pointerEvents = 'none';
      setTimeout(function() {
        splash.style.display = 'none';
        splash.classList.add('hidden');
      }, 400);
    }
    window.initOnboarding();
  }, 1000);
});

// ══════════════════════════════════════════════════════════════════════════════
// 🪔 GUARANTEED BULLETPROOF AARTI COLLECTION MODAL CONTROLLER
// ══════════════════════════════════════════════════════════════════════════════

window.openAartiCollectionModal = function(deityKey) {
  const coll = window.AARTI_COLLECTIONS ? window.AARTI_COLLECTIONS[deityKey] : null;
  if (!coll) {
    console.warn('Aarti collection not found:', deityKey);
    return;
  }

  const modal = document.getElementById('aarti-options-modal');
  if (!modal) return;

  const titleEl = document.getElementById('aarti-modal-title');
  const deityEl = document.getElementById('aarti-modal-deity');
  const mantraEl = document.getElementById('aarti-modal-mantra');
  const imgEl = document.getElementById('aarti-modal-img');
  const listContainer = document.getElementById('aarti-modal-list');

  if (titleEl) titleEl.textContent = coll.title;
  if (deityEl) deityEl.textContent = coll.deity;
  if (mantraEl) mantraEl.textContent = coll.mantra;
  
  if (imgEl) {
    imgEl.src = coll.img;
    imgEl.onerror = function() { this.src = coll.fallbackImg; };
  }

  if (listContainer) {
    listContainer.innerHTML = coll.items.map((item, idx) => `
      <div class="aarti-opt-card" onclick="window.readAartiItemDirect('${deityKey}', ${idx})">
        <div class="aarti-opt-index">0${idx+1}</div>
        <div class="aarti-opt-info">
          <div class="aarti-opt-title">${item.title}</div>
          <div class="aarti-opt-sub">${item.sub}</div>
        </div>
        <div class="aarti-opt-actions">
          <button class="aarti-opt-read-btn" onclick="event.stopPropagation(); window.readAartiItemDirect('${deityKey}', ${idx})" title="पाठ पढ़ें">
            📖 पढ़ें
          </button>
          <button class="aarti-opt-play-btn" onclick="event.stopPropagation(); window.playAartiItemDirect('${deityKey}', ${idx})" title="आरती सुनें">
            ▶
          </button>
        </div>
      </div>
    `).join('');
  }

  modal.classList.remove('hidden');
  modal.classList.add('active');
  modal.style.display = 'flex';
  modal.style.opacity = '1';
  modal.style.pointerEvents = 'auto';

  if (navigator.vibrate) navigator.vibrate(30);
};

window.closeAartiOptionsModal = function() {
  const modal = document.getElementById('aarti-options-modal');
  if (modal) {
    modal.classList.remove('active');
    modal.style.display = 'none';
    modal.style.pointerEvents = 'none';
  }
};

