// ⭐ RATE APP MODAL SYSTEM
// Functions: openRateModal, closeRateModal, submitRating
// ══════════════════════════════════════════════════════════════════════════════

window._currentStarRating = 0;

window.openRateModal = function() {
  const modal = document.getElementById('rate-modal');
  if (!modal) {
    // Fallback: open play store or show alert
    if (typeof showToast === 'function') {
      showToast('⭐ कृपया ऐप स्टोर पर रेट करें!');
    }
    return;
  }
  // Remove hardcoded display:none
  modal.style.setProperty('display', 'flex', 'important');
  modal.classList.remove('hidden');
  modal.style.pointerEvents = 'auto';

  // Reset stars
  window._currentStarRating = 0;
  _updateStarDisplay(0);

  // Close on overlay click
  modal.onclick = function(e) {
    if (e.target === modal) window.closeRateModal();
  };
};

window.closeRateModal = function() {
  const modal = document.getElementById('rate-modal');
  if (!modal) return;
  modal.style.setProperty('display', 'none', 'important');
  modal.classList.add('hidden');
  modal.style.pointerEvents = 'none';
  window._currentStarRating = 0;
};

// Star hover/click handling
function _updateStarDisplay(rating) {
  const stars = document.querySelectorAll('#star-row .star');
  stars.forEach(function(star, i) {
    star.textContent = (i < rating) ? '★' : '☆';
    star.style.color = (i < rating) ? '#F8C83B' : '#CBD5E1';
    star.style.fontSize = (i < rating) ? '2.2rem' : '1.8rem';
    star.style.textShadow = (i < rating) ? '0 0 12px rgba(248,200,59,0.8)' : 'none';
    star.style.transition = 'all 0.15s ease';
  });
}

// Attach star click events after DOM load
document.addEventListener('DOMContentLoaded', function() {
  // Set up star interactions
  const starRow = document.getElementById('star-row');
  if (starRow) {
    starRow.querySelectorAll('.star').forEach(function(star) {
      const val = parseInt(star.getAttribute('data-val')) || 0;

      star.style.cursor = 'pointer';
      star.style.fontSize = '1.8rem';
      star.style.padding = '0 4px';
      star.style.transition = 'all 0.15s ease';
      star.style.color = '#CBD5E1';

      star.addEventListener('click', function() {
        window._currentStarRating = val;
        _updateStarDisplay(val);
        if (navigator.vibrate) navigator.vibrate(25);
      });

      star.addEventListener('mouseenter', function() {
        _updateStarDisplay(val);
      });
    });

    starRow.addEventListener('mouseleave', function() {
      _updateStarDisplay(window._currentStarRating);
    });
  }

  // modal-close buttons
  document.querySelectorAll('[data-close]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      const targetId = btn.getAttribute('data-close');
      const target = document.getElementById(targetId);
      if (target) {
        target.style.setProperty('display', 'none', 'important');
        target.classList.add('hidden');
      }
    });
  });
});

window.submitRating = function() {
  const rating = window._currentStarRating;
  if (rating === 0) {
    if (typeof showToast === 'function') {
      showToast('⭐ कृपया पहले स्टार चुनें');
    }
    return;
  }

  // Save rating
  localStorage.setItem('bhakti_app_rating', rating);
  localStorage.setItem('bhakti_app_rated', 'true');

  // Show thank you message
  if (typeof showToast === 'function') {
    if (rating >= 4) {
      showToast('🙏 आपके ' + rating + ' स्टार के लिए धन्यवाद! जय श्री राम 🚩');
    } else {
      showToast('🙏 आपकी रेटिंग के लिए धन्यवाद! हम बेहतर करेंगे।');
    }
  }

  // Haptic feedback
  if (navigator.vibrate) navigator.vibrate([30, 20, 60]);

  // Close after delay
  setTimeout(function() {
    window.closeRateModal();
  }, 1200);

  // If 5 stars, show extra animation or prompt to review on store
  if (rating === 5) {
    setTimeout(function() {
      // Could redirect to play store
      console.log('[Rate] 5 star rating submitted!');
    }, 1500);
  }
};



// ══════════════════════════════════════════════════════════════════════════════
// 🖥️ DESKTOP LAYOUT MANAGER
// On 1024px+: sidebar is always visible, drawer toggling disabled
// On phone/tablet: normal drawer behavior
// ══════════════════════════════════════════════════════════════════════════════

window._isDesktop = function() {
  return window.innerWidth >= 1024;
};

// Override openDrawer for desktop - no-op
var _originalOpenDrawer = window.openDrawer;
window.openDrawer = function() {
  if (window._isDesktop()) return; // sidebar always visible on desktop
  if (typeof _originalOpenDrawer === 'function') _originalOpenDrawer();
};

var _originalCloseDrawer = window.closeDrawer;
window.closeDrawer = function() {
  if (window._isDesktop()) return; // sidebar always visible on desktop
  if (typeof _originalCloseDrawer === 'function') _originalCloseDrawer();
};

// On resize: manage sidebar visibility
function _handleDesktopResize() {
  var drawer = document.querySelector('.side-drawer');
  var overlay = document.querySelector('.overlay');
  var hamburger = document.getElementById('hamburger-btn');

  if (window._isDesktop()) {
    // Desktop: show sidebar always
    if (drawer) {
      drawer.style.transform = 'translateX(0)';
      drawer.style.visibility = 'visible';
      drawer.style.opacity = '1';
      drawer.style.display = 'block';
      drawer.style.pointerEvents = 'auto';
      drawer.classList.remove('closed');
      drawer.classList.add('dt-open');
    }
    if (overlay) {
      overlay.style.display = 'none';
      overlay.style.opacity = '0';
      overlay.style.pointerEvents = 'none';
    }
    if (hamburger) hamburger.style.display = 'none';

    // Make nav items in drawer active on desktop
    _syncDrawerActiveItem();

  } else {
    // Mobile/Tablet: close sidebar
    if (drawer) {
      drawer.classList.remove('dt-open');
      // Let original logic handle it
      if (!drawer.classList.contains('open')) {
        drawer.style.transform = 'translateX(-100%)';
        drawer.style.opacity = '0.95';
      }
    }
    if (hamburger) hamburger.style.display = '';
  }
}

// Sync active drawer item with current page
function _syncDrawerActiveItem() {
  var currentPage = document.querySelector('.page.active');
  if (!currentPage) return;
  var pageId = currentPage.id;

  document.querySelectorAll('.drawer-item').forEach(function(item) {
    var target = item.getAttribute('data-page') || '';
    if (target === pageId) {
      item.classList.add('active');
      item.style.background = 'rgba(248,200,59,0.18)';
      item.style.color = '#F8C83B';
    } else {
      item.classList.remove('active');
      item.style.background = '';
      item.style.color = '';
    }
  });
}

// Run on load and resize
document.addEventListener('DOMContentLoaded', function() {
  _handleDesktopResize();

  // Update active item when pages change
  document.querySelectorAll('.drawer-item[data-page]').forEach(function(item) {
    item.addEventListener('click', function() {
      setTimeout(_syncDrawerActiveItem, 100);
    });
  });
});

window.addEventListener('resize', function() {
  clearTimeout(window._resizeTimer);
  window._resizeTimer = setTimeout(_handleDesktopResize, 100);
});



// Hook to ensure Sankashti renders whenever page-sankashti is opened
const _origShowPageSankashti = window.showPage;
window.showPage = function(pageId) {
  if(pageId === 'page-sankashti' && typeof renderDrikSankashti === 'function') {
    renderDrikSankashti('sk-dates-container');
    renderDrikSankashti('sankashti-dates-container');
  }
  if(typeof _origShowPageSankashti === 'function') {
    return _origShowPageSankashti(pageId);
  }
};



