// Direct audio/video player
window.playChalisaItemDirect = function(deityKey, idx) {
  const coll = window.CHALISA_COLLECTIONS ? window.CHALISA_COLLECTIONS[deityKey] : null;
  if (!coll || !coll.items || !coll.items[idx]) return;

  const item = coll.items[idx];
  if (item.video_id && typeof playYouTubeAudio === 'function') {
    playYouTubeAudio(item.video_id, item.title, coll.deity);
  } else if (item.audio_url && typeof playAudioUrl === 'function') {
    playAudioUrl(item.audio_url, item.title, coll.deity);
  } else {
    window.readChalisaItemDirect(deityKey, idx, 'audio');
    if (window.AiBhaktiPlayer) {
      window.AiBhaktiPlayer.togglePlay();
    }
  }
};

// 3. Render Full Sanatan Panchang Chalisa Page (page-chalisa)
window._drikChalisaCurrentFilter = 'all';
window._drikChalisaCurrentSearch = '';

window.renderFullDrikChalisaPage = function(filterCategory, searchQuery) {
  if (filterCategory !== undefined) window._drikChalisaCurrentFilter = filterCategory;
  if (searchQuery !== undefined) window._drikChalisaCurrentSearch = searchQuery.toLowerCase().trim();

  const container = document.getElementById('drik-chalisa-cards-container');
  const pillsContainer = document.getElementById('drik-chalisa-page-pills');
  if (!container) return;

  const categories = [
    ['all', '✨ सभी (42)'],
    ['devtas', '🔱 देवताओं की चालीसा (21)'],
    ['devis', '🌸 देवियों की चालीसा (21)']
  ];

  if (pillsContainer && pillsContainer.children.length === 0) {
    pillsContainer.innerHTML = categories.map(([k, label]) => `
      <button class="drik-page-chip ${k === window._drikChalisaCurrentFilter ? 'active' : ''}" data-cat="${k}" onclick="window.renderFullDrikChalisaPage('${k}', window._drikChalisaCurrentSearch)">
        ${label}
      </button>
    `).join('');
  } else if (pillsContainer) {
    pillsContainer.querySelectorAll('.drik-page-chip').forEach(btn => {
      if (btn.getAttribute('data-cat') === window._drikChalisaCurrentFilter) {
        btn.classList.add('active');
      } else {
        btn.classList.remove('active');
      }
    });
  }

  let html = '';
  const search = window._drikChalisaCurrentSearch;
  const filter = window._drikChalisaCurrentFilter;

  // Iterate over all collections and group/filter
  Object.keys(window.CHALISA_COLLECTIONS).forEach(catKey => {
    const coll = window.CHALISA_COLLECTIONS[catKey];
    if (!coll) return;

    let items = coll.items;
    
    // Filter by section
    if (filter === 'devtas') {
      items = items.filter(i => i.section === 'देवताओं की चालीसा' || ['hanuman', 'ganesh', 'shiva', 'shani', 'krishna', 'rama', 'surya', 'vishnu', 'bhairav', 'khatushyam'].includes(catKey));
    } else if (filter === 'devis') {
      items = items.filter(i => i.section === 'देवियों की चालीसा' || ['durga', 'gayatri', 'lakshmi', 'ganga', 'saraswati', 'radha', 'devi'].includes(catKey));
    }

    // Filter by search
    if (search) {
      items = items.filter(i => 
        i.title.toLowerCase().includes(search) || 
        i.en_line.toLowerCase().includes(search) || 
        i.hi_line.includes(search) ||
        coll.title.includes(search) ||
        coll.deity.includes(search)
      );
    }

    if (items.length === 0) return;

    html += `
      <div class="drik-category-block" style="margin-bottom:1.2rem;">
        <div style="display:flex; align-items:center; justify-content:space-between; margin-bottom:8px; border-bottom:1px solid rgba(248,200,59,0.2); padding-bottom:4px;">
          <div style="font-size:0.95rem; font-weight:900; color:#FDE68A; display:flex; align-items:center; gap:6px;">
            <span>🪔</span> ${coll.title}
          </div>
          <span style="font-size:0.75rem; color:#CBD5E1; background:rgba(255,255,255,0.08); padding:2px 8px; border-radius:10px;">
            ${items.length} चालीसा
          </span>
        </div>
        <div style="display:grid; grid-template-columns:repeat(auto-fit, minmax(280px, 1fr)); gap:10px;">
          ${items.map(item => {
            const realIdx = coll.items.findIndex(it => it.id === item.id);
            return window.renderDrikChalisaCardHtml(item, catKey, coll, realIdx >= 0 ? realIdx : 0);
          }).join('')}
        </div>
      </div>
    `;
  });

  if (!html) {
    container.innerHTML = `
      <div style="text-align:center; padding:3rem 1rem; color:#94A3B8;">
        <div style="font-size:2.5rem; margin-bottom:10px;">🔍</div>
        <div style="font-size:1.1rem; font-weight:700; color:#FFFDF8;">कोई चालीसा नहीं मिली</div>
        <div style="font-size:0.85rem; margin-top:4px;">कृपया अन्य शब्द लिखकर खोजें</div>
      </div>
    `;
  } else {
    container.innerHTML = html;
  }
};



// ══════════════════════════════════════════════════════════════════════════════
// 🚀 IN-APP UPDATE CHECKER ENGINE
// ══════════════════════════════════════════════════════════════════════════════

function compareAppSemver(v1, v2) {
  if (!v1 || !v2) return 0;
  const p1 = ('' + v1).replace(/^v/, '').split('.').map(n => parseInt(n, 10) || 0);
  const p2 = ('' + v2).replace(/^v/, '').split('.').map(n => parseInt(n, 10) || 0);
  for (let i = 0; i < Math.max(p1.length, p2.length); i++) {
    const n1 = p1[i] || 0;
    const n2 = p2[i] || 0;
    if (n1 > n2) return 1;
    if (n1 < n2) return -1;
  }
  return 0;
}

window.APP_UPDATE_CONFIG = {
  currentVersionCode: 17,
  currentVersionName: '1.15.0',
  manifestUrls: [
    'https://cdn.jsdelivr.net/gh/mishravishwanath86-bot/Bhakti-me-leen@main/version.json',
    'https://api.github.com/repos/mishravishwanath86-bot/Bhakti-me-leen/contents/version.json',
    'https://api.github.com/repos/mishravishwanath86-bot/Bhakti-me-leen/releases/latest',
    'https://raw.githubusercontent.com/mishravishwanath86-bot/Bhakti-me-leen/main/version.json'
  ],
  downloadUrl: 'https://github.com/mishravishwanath86-bot/Bhakti-me-leen/releases/latest/download/bhakti-app.apk',
  latestReleaseInfo: null,
  isChecking: false
};

window.checkForAppUpdates = async function(isManualUserCheck = false) {
  if (window.APP_UPDATE_CONFIG.isChecking) return;
  window.APP_UPDATE_CONFIG.isChecking = true;

  if (isManualUserCheck && typeof showToast === 'function') {
    showToast('🔄 नए अपडेट की जांच हो रही है...');
  }

  let updateData = null;

  for (const endpoint of window.APP_UPDATE_CONFIG.manifestUrls) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 4500);
      const cacheBust = endpoint.includes('?') ? '&_t=' + Date.now() : '?_t=' + Date.now();

      const resp = await fetch(endpoint + cacheBust, {
        signal: controller.signal,
        headers: { 'Accept': 'application/json' }
      });
      clearTimeout(timeoutId);

      if (!resp.ok) continue;
      const raw = await resp.json();

      // Case 1: GitHub /contents/ API (base64 payload)
      if (raw && raw.content && raw.encoding === 'base64') {
        try {
          const decodedStr = decodeURIComponent(escape(atob(raw.content.replace(/\s/g, ''))));
          updateData = JSON.parse(decodedStr);
          if (updateData && (updateData.versionCode || updateData.versionName)) break;
        } catch (_) {}
      }
      // Case 2: Direct version.json (jsDelivr or Raw GitHub)
      else if (raw && (raw.versionCode || raw.versionName)) {
        updateData = raw;
        break;
      }
      // Case 3: GitHub /releases/latest API
      else if (raw && raw.tag_name) {
        const apkAsset = Array.isArray(raw.assets) ? raw.assets.find(a => a.name && a.name.endsWith('.apk')) : null;
        const tagVer = raw.tag_name.replace(/^v/, '');
        updateData = {
          versionCode: 0,
          versionName: tagVer,
          apkUrl: apkAsset ? apkAsset.browser_download_url : `https://github.com/mishravishwanath86-bot/Bhakti-me-leen/releases/download/${raw.tag_name}/bhakti-app.apk`,
          title: raw.name || `पावन अपडेट v${tagVer} उपलब्ध है! 🚀`,
          releaseNotes: raw.body ? raw.body.split('\n').map(l => l.trim()).filter(l => l.length > 0) : ['समस्त पावन फीचर्स व सुधार'],
          forceUpdate: false
        };
        break;
      }
    } catch (e) {
      // Endpoint timed out or blocked by ISP; continue to next mirror
    }
  }

  window.APP_UPDATE_CONFIG.isChecking = false;

  if (!updateData) {
    console.log('[UpdateChecker] Offline or mirrors unreachable');
    if (isManualUserCheck && typeof showToast === 'function') {
      showToast(`ℹ️ वर्तमान संस्करण: v${window.APP_UPDATE_CONFIG.currentVersionName} (इंटरनेट उपलब्ध होने पर पुनः जांचें)`);
    }
    return;
  }

  window.APP_UPDATE_CONFIG.latestReleaseInfo = updateData;
  if (updateData.apkUrl) {
    window.APP_UPDATE_CONFIG.downloadUrl = updateData.apkUrl;
  }

  const remoteCode = parseInt(updateData.versionCode || 0, 10);
  const currentCode = window.APP_UPDATE_CONFIG.currentVersionCode;
  const currentName = window.APP_UPDATE_CONFIG.currentVersionName;
  const remoteName = updateData.versionName;

  let isNewer = false;
  if (remoteName && currentName) {
    const cmp = compareAppSemver(remoteName, currentName);
    if (cmp > 0) {
      isNewer = true;
    } else if (cmp < 0) {
      isNewer = false;
    } else {
      isNewer = remoteCode > currentCode && remoteCode > 0;
    }
  } else if (remoteCode > 0 && currentCode > 0) {
    isNewer = remoteCode > currentCode;
  }

  if (isNewer) {
    // 1. Show Red Badge in Drawer and Settings
    const badges = document.querySelectorAll('#update-badge, .update-badge');
    badges.forEach(b => { b.style.display = 'inline-block'; });

    // 2. Show persistent Top Update Notification Banner
    const topBanner = document.getElementById('app-update-top-banner');
    const bannerTag = document.getElementById('banner-version-tag');
    if (topBanner) {
      if (bannerTag && updateData.versionName) bannerTag.textContent = 'v' + updateData.versionName;
      topBanner.style.display = 'flex';
    }

    // 3. Open full modal popup if NOT dismissed or downloaded
    const verKey = updateData.versionName || updateData.versionCode;
    const dismissedKey = 'dismissed_update_v' + verKey;
    const downloadedKey = 'downloaded_update_v' + verKey;
    const wasDismissed = (localStorage.getItem(dismissedKey) === 'true') || 
                         (localStorage.getItem(downloadedKey) === 'true') ||
                         (sessionStorage.getItem(dismissedKey) === 'true');

    if (isManualUserCheck) {
      window.openUpdateModal(updateData);
    } else if (updateData.forceUpdate) {
      window.openUpdateModal(updateData);
    } else if (!wasDismissed) {
      window.openUpdateModal(updateData);
    }
  } else {
    // App is up to date! Ensure all update banners, badges, and modals are hidden
    const badges = document.querySelectorAll('#update-badge, .update-badge');
    badges.forEach(b => { b.style.display = 'none'; });

    const topBanner = document.getElementById('app-update-top-banner');
    if (topBanner) topBanner.style.display = 'none';

    const modal = document.getElementById('app-update-modal');
    if (modal) modal.style.display = 'none';

    if (isManualUserCheck && typeof showToast === 'function') {
      showToast(`✅ आपका ऐप नवीनतम संस्करण पर है (v${window.APP_UPDATE_CONFIG.currentVersionName})!`);
    }
  }
};

window.openUpdateModal = function(data) {
  const modal = document.getElementById('app-update-modal');
  if (!modal) return;

  const versionTag = document.getElementById('update-version-tag');
  if (versionTag && data.versionName) versionTag.textContent = 'v' + data.versionName;

  const titleEl = document.getElementById('update-title-text');
  if (titleEl && data.title) titleEl.textContent = data.title;

  const notesList = document.getElementById('update-notes-list');
  if (notesList && Array.isArray(data.releaseNotes)) {
    notesList.innerHTML = data.releaseNotes.map(n => `<li>${n}</li>`).join('');
  }

  if (data.apkUrl) {
    window.APP_UPDATE_CONFIG.downloadUrl = data.apkUrl;
  }

  const dwnBtn = document.getElementById('update-download-btn');
  if (dwnBtn && data.apkSize) {
    dwnBtn.innerHTML = `<span>📲</span> अभी अपडेट डाउनलोड करें (${data.apkSize}) ➔`;
  }

  const laterBtn = document.getElementById('update-later-btn');
  const closeBtn = document.getElementById('update-modal-close-btn');
  if (data.forceUpdate) {
    if (laterBtn) laterBtn.style.display = 'none';
    if (closeBtn) closeBtn.style.display = 'none';
  } else {
    if (laterBtn) laterBtn.style.display = 'block';
    if (closeBtn) closeBtn.style.display = 'flex';
  }

  modal.style.display = 'flex';
  if (navigator.vibrate) navigator.vibrate([40, 30, 80]);
  if (typeof showToast === 'function') {
    showToast('🚀 नया पावन अपडेट v' + (data.versionName || '1.11.0') + ' उपलब्ध है!');
  }
};

window.closeUpdateModal = function() {
  const modal = document.getElementById('app-update-modal');
  if (modal) modal.style.display = 'none';
  if (window.APP_UPDATE_CONFIG.latestReleaseInfo) {
    const v = window.APP_UPDATE_CONFIG.latestReleaseInfo.versionName || window.APP_UPDATE_CONFIG.latestReleaseInfo.versionCode;
    try {
      localStorage.setItem('dismissed_update_v' + v, 'true');
      sessionStorage.setItem('dismissed_update_v' + v, 'true');
    } catch (_) {}
  }
};

window.triggerApkDownload = function() {
  const url = window.APP_UPDATE_CONFIG.downloadUrl;
  if (!url) return;

  // Immediately close modal & hide top banner so popup vanishes
  window.closeUpdateModal();
  const topBanner = document.getElementById('app-update-top-banner');
  if (topBanner) topBanner.style.display = 'none';

  const info = window.APP_UPDATE_CONFIG.latestReleaseInfo;
  if (info) {
    const v = info.versionName || info.versionCode;
    try {
      localStorage.setItem('dismissed_update_v' + v, 'true');
      localStorage.setItem('downloaded_update_v' + v, 'true');
      sessionStorage.setItem('dismissed_update_v' + v, 'true');
    } catch (_) {}
  }

  if (typeof showToast === 'function') {
    showToast('📥 पावन अपडेट डाउनलोड शुरू हो रहा है...');
  }

  if (window.AndroidBridge && typeof window.AndroidBridge.downloadApk === 'function') {
    window.AndroidBridge.downloadApk(url);
  } else {
    window.open(url, '_system');
  }
};

// Automatic silent background check on launch
setTimeout(() => {
  window.checkForAppUpdates(false);
}, 2500);


