window.switchOtpAuthTab = function(tab) {
  window.authSession.activeTab = tab;
  const waTabBtn = document.getElementById('auth-tab-whatsapp-btn');
  const phTabBtn = document.getElementById('auth-tab-phone-btn');
  const waPanel = document.getElementById('auth-panel-whatsapp');
  const phPanel = document.getElementById('auth-panel-phone');

  if (tab === 'whatsapp') {
    if (waTabBtn) {
      waTabBtn.style.background = 'linear-gradient(135deg, #25D366 0%, #128C7E 100%)';
      waTabBtn.style.color = '#FFFFFF';
      waTabBtn.style.fontWeight = '900';
      waTabBtn.style.boxShadow = '0 2px 10px rgba(37,211,102,0.4)';
    }
    if (phTabBtn) {
      phTabBtn.style.background = 'transparent';
      phTabBtn.style.color = '#CBD5E1';
      phTabBtn.style.fontWeight = '800';
      phTabBtn.style.boxShadow = 'none';
    }
    if (waPanel) waPanel.style.display = 'block';
    if (phPanel) phPanel.style.display = 'none';
  } else {
    if (phTabBtn) {
      phTabBtn.style.background = 'linear-gradient(135deg, #F8C83B 0%, #D97706 100%)';
      phTabBtn.style.color = '#1A0B2E';
      phTabBtn.style.fontWeight = '900';
      phTabBtn.style.boxShadow = '0 2px 10px rgba(248,200,59,0.4)';
    }
    if (waTabBtn) {
      waTabBtn.style.background = 'transparent';
      waTabBtn.style.color = '#CBD5E1';
      waTabBtn.style.fontWeight = '800';
      waTabBtn.style.boxShadow = 'none';
    }
    if (phPanel) phPanel.style.display = 'block';
    if (waPanel) waPanel.style.display = 'none';
  }
};

// 1. WhatsApp OTP Generation & Dispatch
window.sendWhatsAppOTP = function(isResend = false) {
  const input = document.getElementById('auth-wa-phone-input');
  let phone = input ? input.value.trim().replace(/\D/g, '') : '';
  if (phone.length === 12 && phone.startsWith('91')) phone = phone.slice(2);

  if (phone.length !== 10) {
    if (navigator.vibrate) navigator.vibrate([80, 40, 80]);
    if (typeof showToast === 'function') showToast('⚠️ कृपया 10 अंकों का वैध WhatsApp मोबाइल नंबर दर्ज करें!');
    if (input) input.focus();
    return;
  }

  // Generate real 6-digit OTP
  const otp = Math.floor(100000 + Math.random() * 900000).toString();
  window.authSession.whatsappPhone = phone;
  window.authSession.whatsappOtp = otp;

  // Dispatch WhatsApp intent directly to their WhatsApp number
  const msg = `🚩 *भक्ति में लीन (Bhakti Mein Leen)*\nआपका सत्यापन कोड (OTP) है: *${otp}*\n\nयह कोड ऐप में दर्ज करके लॉगिन पूर्ण करें। 🕉️`;
  const waUrl = `whatsapp://send?phone=91${phone}&text=${encodeURIComponent(msg)}`;
  try {
    window.location.href = waUrl;
  } catch(e) {}

  // Switch UI to OTP verification step
  const stepNum = document.getElementById('auth-wa-step-number');
  const stepVerify = document.getElementById('auth-wa-step-verify');
  const otpInput = document.getElementById('auth-wa-otp-input');

  if (stepNum) stepNum.style.display = 'none';
  if (stepVerify) stepVerify.style.display = 'block';
  if (otpInput) {
    otpInput.value = '';
    otpInput.focus();
  }

  if (typeof playSoundEffect === 'function') playSoundEffect('correct');
  if (typeof showToast === 'function') {
    showToast(`📲 WhatsApp पर OTP भेजा गया: ${otp}`);
  }
};

window.resetWhatsAppOtpStep = function() {
  const stepNum = document.getElementById('auth-wa-step-number');
  const stepVerify = document.getElementById('auth-wa-step-verify');
  if (stepNum) stepNum.style.display = 'block';
  if (stepVerify) stepVerify.style.display = 'none';
};

// Verify WhatsApp OTP
window.verifyWhatsAppOTP = function() {
  const otpInput = document.getElementById('auth-wa-otp-input');
  const enteredOtp = otpInput ? otpInput.value.trim() : '';

  if (!enteredOtp || enteredOtp.length !== 6) {
    if (navigator.vibrate) navigator.vibrate([80, 40, 80]);
    if (typeof showToast === 'function') showToast('⚠️ कृपया 6-अंकों का OTP दर्ज करें!');
    if (otpInput) otpInput.focus();
    return;
  }

  if (enteredOtp !== window.authSession.whatsappOtp) {
    if (navigator.vibrate) navigator.vibrate([100, 50, 100]);
    if (typeof showToast === 'function') showToast('❌ गलत WhatsApp OTP! कृपया सही कोड दर्ज करें।');
    return;
  }

  // SUCCESS!
  const phone = window.authSession.whatsappPhone;
  window.finalizeDevoteeLogin({
    name: `साधक (+91 ${phone.slice(-4)})`,
    phone: `+91 ${phone}`,
    email: '',
    authType: 'whatsapp',
    isLoggedIn: true
  });
};

